window.YXA.banks.push({"id":"cx","name":"程序文件题库","group":"竞赛题库","desc":"公司管理规定/程序文件合并题库（可按科目筛选）","source":"程序文件/程序文件题库_合并_离线答题系统.html","builtAt":"2026-10-01 17:55:51","questions":[{"id":"0001","type":"单选题","question":"（ ）是HSE培训的归口管理部门。","options":[{"key":"A","text":"企管法规部"},{"key":"B","text":"人力资源部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"党群工作部"}],"answer":"C","explanation":"","subject":"HSE培训管理规定"},{"id":"0002","type":"单选题","question":"生产经营单位主要负责人，必须接受专门的HSE培训，取得（）后，方可任职。","options":[{"key":"A","text":"上岗证"},{"key":"B","text":"安全合格证"},{"key":"C","text":"安全资格证"}],"answer":"B","explanation":"","subject":"HSE培训管理规定"},{"id":"0003","type":"单选题","question":"新入厂员工必须经过厂、车间、班组三级HSE培训，考试合格后持证上岗，时间不得少于（ ）学时。","options":[{"key":"A","text":"24"},{"key":"B","text":"36"},{"key":"C","text":"72"},{"key":"D","text":"96"}],"answer":"C","explanation":"","subject":"HSE培训管理规定"},{"id":"0004","type":"单选题","question":"班组要坚持开展安全活动，安全活动要做到有有计划、有内容、有记录，每月班组安全活动计划应由车间结合上级要求及本单位安全生产情况统一安排。班组安全活动应建立《班组安全活动台帐》，基层班组安全活动（）","options":[{"key":"A","text":"每周1次，每月不少于4小时"},{"key":"B","text":"基层班组安全活动每月4次，安全活动每月累计总时间不少于两个小时。"},{"key":"C","text":"每半月1次，每月不少于两小时"},{"key":"D","text":"每半月1次，累计不少于4小时"}],"answer":"B","explanation":"","subject":"HSE培训管理规定"},{"id":"0005","type":"单选题","question":"班组安全活动必须全员参加，除连续休产假、病假、借调等超过（）的人员外，未参加人员要补学签名。","options":[{"key":"A","text":"6个月"},{"key":"B","text":"3个月"},{"key":"C","text":"12个月"},{"key":"D","text":"1个月"}],"answer":"A","explanation":"","subject":"HSE培训管理规定"},{"id":"0006","type":"多选题","question":"以下哪些管理人员需要参加班组安全活动，对其进行检查、指导。","options":[{"key":"A","text":"基层单位负责人"},{"key":"B","text":"上级领导"},{"key":"C","text":"职能部门负责人"},{"key":"D","text":"职能部门管理人员"}],"answer":"ABC","explanation":"","subject":"HSE培训管理规定"},{"id":"0007","type":"多选题","question":"培训方式包括：典型课堂培训、（）、（）、（）、岗位实际练习、网络培训","options":[{"key":"A","text":"集中培训"},{"key":"B","text":"应急演练"},{"key":"C","text":"安全经验分享"},{"key":"D","text":"岗位练兵"}],"answer":"ABCD","explanation":"","subject":"HSE培训管理规定"},{"id":"0008","type":"单选题","question":"施工作业安全监护人员取证培训必须由（）组织实施","options":[{"key":"A","text":"培训中心"},{"key":"B","text":"所在车间"},{"key":"C","text":"直属单位"},{"key":"D","text":"直属单位安全组"}],"answer":"A","explanation":"","subject":"HSE培训管理规定"},{"id":"0009","type":"单选题","question":"员工的个人HSE培训记录应妥善地保存在员工的岗位上，随时更新。个人HSE培训计划及记录应至少保存（）。","options":[{"key":"A","text":"1年"},{"key":"B","text":"2年"},{"key":"C","text":"3年"},{"key":"D","text":"5年"}],"answer":"C","explanation":"","subject":"HSE培训管理规定"},{"id":"0010","type":"判断题","question":"员工脱离操作岗位（休产假、病假、外出学习等）一年以上重新上岗时，必须重新进行车间级、班组级HSE培训。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"员工脱离操作岗位半年以上重新上岗时，应重新进行直属单位级/车间级、班组级HSE培训，各层级不少于8学时；题干写成“一年以上”且仅列车间级、班组级，均不正确。","subject":"HSE培训管理规定"},{"id":"0011","type":"单选题","question":"( )是公司工艺操作工作循环分析的归口管理部门，负责制定工艺操作工作循环分析管理制度，并督察制度的执行。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0012","type":"判断题","question":"工作循环分析（JCA）是以操作主管和员工合作的方式对已经制定的操作程序和员工实际操作行为进行分析和评价的一种方法。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0013","type":"判断题","question":"操作主管是负责执行工作循环分析计划的人员，一般是由基层单位工艺、设备等专业技术人员及班组长（站、队长）担任。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0014","type":"判断题","question":"关键操作是指可能对有关的个人或组织带来重大危害和影响的生产操作活动，或者与关键设备有关联的活动。包括但不限于：新增操作、工艺和设备变更、事故处理、专用设备相关的操作等。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0015","type":"判断题","question":"协调员是负责制定工作循环分析计划并组织实施的人员，一般由基层单位主管生产、技术、设备的负责人担任。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0016","type":"判断题","question":"在实际操作前，操作主管应和操作员工讨论目前该项工作实际操作情况，以及实际操作与书面规程的差异。若员工第一次进行工作循环分析，操作主管不用事先向员工解释工作循环分析的目的、作用和程序。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"员工第一次进行工作循环分析时，操作主管应事先向员工解释工作循环分析的目的、作用和程序，而不是“不用事先解释”。","subject":"工艺操作工作循环分析管理规定"},{"id":"0017","type":"判断题","question":"操作主管应将观察到的不一致项、修订规程和整改隐患的建议、负责人及其实施日期，形成记录，通过技术管理系统上报协调员。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0018","type":"单选题","question":"协调员应定期组织对工作循环分析完成情况、操作卡的修订及操作主管上报的评估记录进行汇总、统计、分析，经评审操作卡需要修订的，按操作卡管理程序（）内组织完成修订审批工作。","options":[{"key":"A","text":"1周"},{"key":"B","text":"1月"},{"key":"C","text":"1.5月"},{"key":"D","text":"3月"}],"answer":"B","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0019","type":"判断题","question":"所有修订后发布的操作规程或操作卡在实施之前，确保相关员工都能及时得到培训。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0020","type":"判断题","question":"协调员组织对本单位的所有工艺操作进行清理，按照《生产装置操作卡管理规定》要求建立装置操作卡统计表，识别出关键操作，动态更新。对照现有操作卡，评估其完整性。如果现有操作卡没有涵盖识别出的工艺操作活动，则按照要求进行补充完善。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0021","type":"单选题","question":"所有与关键操作相关的操作卡每（）年至少分析一次，其他的操作卡可视情况而定。大检修开停工、试生产、检维修工艺处理等操作卡每次使用前组织评审、会签，不要求年度集中JCA评审。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"5"}],"answer":"A","explanation":"","subject":"工艺操作工作循环分析管理规定"},{"id":"0022","type":"判断题","question":"在验证过程中发现有隐患不应立即停止操作，并现场整改(包括现场隐患和操作卡缺陷)，当时整改不了的应采取控制和防范措施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"验证过程中发现有隐患，应立即停止操作并现场整改；当时整改不了的应采取控制和防范措施，不是“不应立即停止操作”。","subject":"工艺操作工作循环分析管理规定"},{"id":"0023","type":"单选题","question":"( )是公司生产装置操作平稳率的归口管理部门，负责组织确定下达各装置平稳率控制点指标，负责转化总部相应的文件、对文件的执行情况进行抽查与考核。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量健康安环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"A","explanation":"","subject":"操作平稳率管理规定"},{"id":"0024","type":"单选题","question":"新的装置平稳率指标明细表及变更审批单下发后，（）个工作日内旧版资料标示为“作废”或“删除”。","options":[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}],"answer":"C","explanation":"","subject":"操作平稳率管理规定"},{"id":"0025","type":"判断题","question":"平稳率指标明细表每年评审修订换版一次,对上一版平稳率明细表执行期间发生的变更进行内容修订。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"操作平稳率管理规定"},{"id":"0026","type":"判断题","question":"工艺卡片指标换版完成后，相应的平稳率指标十天内完成换版。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"工艺卡片指标变更涉及平稳率指标变更时，平稳率指标应随工艺卡片指标同步变更，不是换版完成后十天内再换版。","subject":"操作平稳率管理规定"},{"id":"0027","type":"判断题","question":"平稳率指标管理采用平台线上进行。平台故障维护期间，发生的线下平稳率管理审核审批，应在平台恢复后5个工作日内完成平稳率管理平台审核审批。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"平台故障维护期间发生的线下平稳率管理审核审批，应在平台恢复后3个工作日内完成平台审核审批，不是5个工作日。","subject":"操作平稳率管理规定"},{"id":"0028","type":"判断题","question":"新的装置平稳率指标明细表及变更审批单下发后，旧的资料必须撤离现场。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"操作平稳率管理规定"},{"id":"0029","type":"判断题","question":"操作平稳率由班组员工进行控制，班组运行工程师（装置班长或副班长）具体负责各级控制点的监督，随时检查操作工艺参数的波动情况，发现超差及时进行调整并分析原因，交班前在MES系统装置平稳率模块平稳率偏差原因栏中如实填写偏差产生原因、调整经过和控制措施，并提交审核，由于MES统计的原因无法在交班前完成的要在下一个当班期间完成补录。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"操作平稳率管理规定"},{"id":"0030","type":"判断题","question":"直属生产单位属地技术人员负责每天对班组提出的各级平稳率控制点工艺参数偏差原因进行确认，向直属生产单位工艺负责人汇报工艺参数波动情况，并对直属单位级平稳率剔除申请进行审核，对公司级平稳率剔除申请报请公司生产运行部装置工程师进行审核。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"操作平稳率管理规定"},{"id":"0031","type":"单选题","question":"装置开工在产品质量全部合格后，操作正常（）小时后开始统计平稳率","options":[{"key":"A","text":"4"},{"key":"B","text":"8"},{"key":"C","text":"12"},{"key":"D","text":"24"}],"answer":"D","explanation":"","subject":"操作平稳率管理规定"},{"id":"0032","type":"单选题","question":"工艺指标变更涉及总部MES平稳率控制点名称、位号、上下限变更，由直属单位平稳率主管人员在审批完成后（）个工作日内在总部MES系统中进行变更申请。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"5"}],"answer":"D","explanation":"","subject":"操作平稳率管理规定"},{"id":"0033","type":"单选题","question":"( )是操作卡的归口管理部门，负责制定生产装置操作卡相关管理制度，并监督检查制度的执行。整体指导操作卡的编制，负责督察岗位操作卡、事故处理操作卡、开停工操作卡及其他类操作卡中涉及本专业内容的执行。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0034","type":"单选题","question":"直属单位（）是本单位生产装置操作卡的归口管理。负责监督检查公司相关制度在本单位的执行。具体负责组织岗位操作卡、事故处理操作卡、开、停工操作卡及其他类操作卡涉及本专业内容的审核、汇签、修订、检查与考核。","options":[{"key":"A","text":"设备组"},{"key":"B","text":"生产组"},{"key":"C","text":"安全组"},{"key":"D","text":"技术组"}],"answer":"B","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0035","type":"多选题","question":"生产装置操作卡：是生产装置操作规程的卡片化，即将操作规程中操作部分的内容卡片化便于执行和管理。具体内容包括：装置岗位操作卡、（）、事故处理操作卡、单项作业操作卡、通用设备操作卡和其他操作卡共八个种类，分别对应操作规程中操作指南、开工规程、停工规程、专用设备规程、事故处理规程、基础操作规程的部分内容、基础操作规程和操作规定。","options":[{"key":"A","text":"装置开工操作卡"},{"key":"B","text":"装置停工操作卡"},{"key":"C","text":"专用设备操作卡"},{"key":"D","text":"事故处理操作卡"}],"answer":"ABCD","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0036","type":"单选题","question":"除以上操作卡类型外，为加强管理，将转试产、（）等过程要求编制的操作卡纳入其他类操作卡管理的范围，工具的使用、拆打盲板、绑胶皮管、更换压力表、拆装阀门等需作业票控制风险的作业过程不属于生产装置操作卡管理的范围。","options":[{"key":"A","text":"日常检维修工艺处理操作卡"},{"key":"B","text":"取样操作卡"},{"key":"C","text":"泵切换操作卡"},{"key":"D","text":"动作卡"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0037","type":"判断题","question":"装置岗位操作卡、开、停工操作卡、专用设备操作卡、事故处理操作卡、单项作业操作卡、通用设备操作卡、其他操作卡具体内容和格式要求参照附录A执行。转产、试产操作卡内容由直属单位确定。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0038","type":"判断题","question":"操作卡的评审执行《工艺操作工作循环分析管理规定》。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0039","type":"判断题","question":"大检修开停工、试生产、检维修工艺处理等操作卡每次使用前组织评审、会签，如果无变动可继续使用。操作卡随合订本操作规程进行换版。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0040","type":"判断题","question":"联合运行部、研究院中试装置、铁路运输公司炼油联合站、供水供电公司供水运行中心操作卡全部为直属单位级，热电厂生产装置操作卡按照内容的重要性和影响范围分两级管理：分厂级、车间级。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0041","type":"判断题","question":"热电厂分厂级操作卡包括：装置开工操作卡、装置停工操作卡、专用设备操作卡、事故处理操作卡以及部分风险较大的单项作业操作卡和其他操作卡（如转试产、检维修工艺处理等）。分厂级操作卡由车间组织编制，经车间主任审批后报分厂技术部门组织调度、机动、安全质量环保等相关部门审核会签，公司主管领导批准后方可生效执行。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"热电厂分厂级操作卡由车间组织编制，经车间主任审批后报分厂技术部门组织审核会签，由分厂主管领导批准后生效执行，不是公司主管领导批准。","subject":"生产装置操作卡管理规定"},{"id":"0042","type":"判断题","question":"热电厂车间级操作卡包括：装置岗位操作卡、通用设备操作卡以及风险较小的单项作业操作卡和其他操作卡。操作卡编制完成后，经车间（站、队）相关专业会审、车间主任批准后方可生效执行。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0043","type":"判断题","question":"操作卡按要求放置在操作室的资料柜中，须注明名称，并以不同颜色的文件夹加以区分，操作卡封面审批页必须加盖“受控”章，单类操作卡涉及多项操作内容的操作卡在执行时在每一项操作卡的首页加盖“受控”章。 a) 事故处理操作卡存放在红色文件夹内； b) 其他操作卡分别放在不同的蓝色文件夹内。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0044","type":"判断题","question":"操作过程中，内操指挥外操严格按照操作步骤执行操作，外操每执行一步必须及时汇报给内操，由内操统一在操作步骤前划“√”，关键步骤处签署操作时间。操作者在完成一系列操作动作后，需对照操作卡确认无误，关键步骤需签署自己的姓名。本班操作结束，下班前由班组运行工程师(或班组长)确认本班操作无误后，在本班操作的最后一步下画横线（一个班次内可以完成的操作卡可不画线）并签署运行工程师(或班组长)姓名和时间（年/月/日）。做到操作有监控，步步有确认。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0045","type":"判断题","question":"在紧急情况下事故处理操作卡和其他相关操作卡如来不及填写，可在装置达到稳定状态后再签字确认。对于紧急情况下无相应操作卡时，应由相关领导或值班干部组织技术人员、班长、运行工程师等讨论确定处理方案，指挥班组按照处理方案进行处理，事后直属单位（热电厂基层单位）组织讨论并编制相应操作卡进行补充完善。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0046","type":"判断题","question":"操作卡在执行过程中如与实际不符，在相关内容下划“_”标出，由直属单位负责人（热电厂基层单位负责人）在操作卡相对应的步骤旁注明修改原因和修改意见签名后执行。单位负责人不在场时可由直属单位（热电厂基层单位）技术员或值班干部请示直属单位负责人（热电厂基层单位负责人），得到授权同意后对修改意见进行签字确认，事后由直属单位负责人（热电厂基层单位负责人）补签，如单页变动内容较多，直属单位负责人（热电厂基层单位负责人）可统一进行签字确认。对安全生产影响较大并且基层单位无权独自确认的修改内容，按该操作卡原会签程序重新组织会签后执行。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0047","type":"判断题","question":"对操作频次较高、风险较小的操作卡（如一般机泵开停和切换、取样、三剂配置和加注等操作），由直属单位（热电厂基层单位）循环分析工作小组进行评估固化。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0048","type":"单选题","question":"操作卡在执行过程中有偏差的，执行完后（）内，组织对操作卡执行情况和内容进行总结评估和技术分析，需要修订的，一个月内组织完成修订审批替换工作。","options":[{"key":"A","text":"2周"},{"key":"B","text":"1月"},{"key":"C","text":"1.5月"},{"key":"D","text":"3月"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0049","type":"判断题","question":"根据5.4.10和5.4.11要求结合装置实际情况，评估明确出本单位固化操作卡，汇总成表通过工艺技术管理系统经直属单位负责人（热电厂基层单位负责人）审批后归档，批准后的固化操作卡申请审批表及相应操作卡放置现场指定位置，操作人员参照执行。固化操作卡申请审批表模板参考附录B。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产装置操作卡管理规定"},{"id":"0050","type":"单选题","question":"旋转机械状态监测季报（电子记录，由研究院编制，各直属单位使用，保存( )","options":[{"key":"A","text":"1年"},{"key":"B","text":"2年"},{"key":"C","text":"一个大修周期"},{"key":"D","text":"4年"}],"answer":"C","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0051","type":"单选题","question":"（ ）负责本公司转动设备状态监测工作的归口管理，贯彻执行国家、集团公司、股份公司、炼化新材料分公司有关转动设备状态监测管理制度、标准、规定、规程；负责制定本公司转动设备状态监测管理制度，并监督、检查、考核。","options":[{"key":"A","text":"公司机动设备部"},{"key":"B","text":"直属单位"},{"key":"C","text":"车间站队"},{"key":"D","text":"班组"}],"answer":"A","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0052","type":"单选题","question":"其它非生产单位转动设备使用其它（ ）进行监测，监测频次参照5.3.1执行。","options":[{"key":"A","text":"仪表"},{"key":"B","text":"测振仪"},{"key":"C","text":"听诊器"},{"key":"D","text":"便携监测仪器"}],"answer":"D","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0053","type":"多选题","question":"研究院每工作日查看公司关键机组运行数据，结合设备磨损及润滑监测分析结果定期形成报告；关键机组监测数据发现异常反馈（ ）、（ ），对异常开展分析诊断，形成报告。","options":[{"key":"A","text":"公司机动设备部"},{"key":"B","text":"研究院"},{"key":"C","text":"专业公司"},{"key":"D","text":"直属单位"}],"answer":"AD","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0054","type":"多选题","question":"直属单位是机泵管理的第一责任人，检维修人员也应承担相应责任。机泵巡检除应用必要的数字巡检仪器之外，在保证安全的条件下应认真遵循“（ ）、（ ）、（ ）、（ ）、（ ）”五字巡检法。定时按巡回检查路线，对设备进行仔细检查，发现问题，及时解决。","options":[{"key":"A","text":"听"},{"key":"B","text":"摸"},{"key":"C","text":"测"},{"key":"D","text":"看"},{"key":"E","text":"闻"}],"answer":"ABCDE","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0055","type":"单选题","question":"（ ）负责关键机组之外设备振动标准梳理、编制、修订工作。","options":[{"key":"A","text":"研究院"},{"key":"B","text":"机动设备部"},{"key":"C","text":"生产单位"},{"key":"D","text":"机电仪运维中心"}],"answer":"D","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0056","type":"判断题","question":"新建、改、扩建项目在设计阶段应将状态监测系统纳入设计范畴，并与项目同时建设，同步投用。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0057","type":"判断题","question":"在线监测系统应齐全完好、全部投用，监测系统出现异常时，直属单位应及时组织协调处理。在线监测系统的管理、维护及故障处理与生产设备同等对待。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0058","type":"判断题","question":"机泵在线监测异常或报警，第一时间汇报直属单位设备管理人员。直属单位操作人员立即现场确认，时间不能超过2个小时，严禁D区泵运行。直属单位组织分析诊断和处置。现场确认后在报警流程中填写相关信息，提交后由设备管理人员审核，一个工作日关闭报警。判定存在故障按流程生成缺陷，检查、检修验证后一个工作日关闭缺陷流程。报警关闭、缺陷关闭严格按流程要求，专业术语使用规范，描述准确。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0059","type":"判断题","question":"监测发现转动设备异常时，应增加监测频次，必要时采用精密诊断、远程会诊等手段对故障进行分析，及时掌握故障的发展趋势，防止事故发生。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备状态监测管理规定"},{"id":"0060","type":"单选题","question":"在生产场所内从事生产经营活动中，由于受到工艺、制造方法、材料、设备、环境、人的不安全行为等因素影响，发生的意外事件或潜在危险，造成人员轻伤以下或直接经济损失小于()元的情况属于生产安全事件。","options":[{"key":"A","text":"1000"},{"key":"B","text":"5000"},{"key":"C","text":"10000"},{"key":"D","text":"100000"}],"answer":"A","explanation":"","subject":"事故、事件管理规定"},{"id":"0061","type":"单选题","question":"（）负责生产安全事件管理的归口管理。","options":[{"key":"A","text":"经营管理部"},{"key":"B","text":"质量健康安全环保部"},{"key":"C","text":"机动设备部"},{"key":"D","text":"规划和科技信息部"}],"answer":"B","explanation":"","subject":"事故、事件管理规定"},{"id":"0062","type":"单选题","question":"（）负责本专业业务管理职责涉及系统物料和公用工程系统的生产安全事件的统计和分析。","options":[{"key":"A","text":"公司生产运行处"},{"key":"B","text":"质量健康安全环保部"},{"key":"C","text":"机动设备部"},{"key":"D","text":"规划和科技信息部"}],"answer":"A","explanation":"","subject":"事故、事件管理规定"},{"id":"0063","type":"单选题","question":"基层单位负责本车间生产安全事件的统计、分析，制定防范措施并告知（），消除可能造成事故的危害因素，更新风险管理台帐。统计、分析报告上报直属单位安全管理部门。","options":[{"key":"A","text":"员工"},{"key":"B","text":"安全工程师"},{"key":"C","text":"领导"}],"answer":"A","explanation":"","subject":"事故、事件管理规定"},{"id":"0064","type":"单选题","question":"公司对各单位主动上报的各类事件，采取“（）”的原则，鼓励各单位积极主动上报。","options":[{"key":"A","text":"只奖励、不考核"},{"key":"B","text":"自由发挥"},{"key":"C","text":"实事求是"}],"answer":"A","explanation":"","subject":"事故、事件管理规定"},{"id":"0065","type":"单选题","question":"生产安全事件发生后，事件发生单位应在（）内及时如实在“事故事件管理平台”信息系统中填报事件发生的详细经过和事件损害程度。","options":[{"key":"A","text":"8小时"},{"key":"B","text":"5个工作日内"},{"key":"C","text":"48小时"},{"key":"D","text":"72小时"}],"answer":"B","explanation":"","subject":"事故、事件管理规定"},{"id":"0066","type":"单选题","question":"对性质严重、影响恶劣、可能导致严重后果的违章行为和事件或隐瞒不报的事件比照（）事故进行处理。","options":[{"key":"A","text":"车间级"},{"key":"B","text":"考核级"},{"key":"C","text":"公司级"}],"answer":"B","explanation":"","subject":"事故、事件管理规定"},{"id":"0067","type":"单选题","question":"各直属单位、基层车间要对生产安全事件的防范措施定期进行效果验证分析。（每（）一次）","options":[{"key":"A","text":"季度"},{"key":"B","text":"半年"},{"key":"C","text":"年"}],"answer":"B","explanation":"","subject":"事故、事件管理规定"},{"id":"0068","type":"单选题","question":"对于将事故没有按照程序上报，而当成事件录入的，一经发现，按照相应的事故（ ）处罚。","options":[{"key":"A","text":"下限"},{"key":"B","text":"平均值"},{"key":"C","text":"上限"}],"answer":"B","explanation":"","subject":"事故、事件管理规定"},{"id":"0069","type":"多选题","question":"生产安全事件分为以下哪些类：（）","options":[{"key":"A","text":"工业生产安全事件"},{"key":"B","text":"道路交通事件"},{"key":"C","text":"其他事件"}],"answer":"ABC","explanation":"","subject":"事故、事件管理规定"},{"id":"0070","type":"单选题","question":"公司作业许可证的风险级别由低向高分为( )个级别","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":"D","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0071","type":"多选题","question":"作业监护人权限有（）","options":[{"key":"A","text":"确保正确的作业计划"},{"key":"B","text":"相关人员持有效资格证书上岗"},{"key":"C","text":"作业人员配备和使用的个体防护装备满足作业要求"},{"key":"D","text":"作业许可证应与作业内容相符并在有效期内，核查作业许可证中各项安全措施已得到落实"}],"answer":"BCD","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0072","type":"多选题","question":"不需要作业风险评估许可证的工作有（ ）：","options":[{"key":"A","text":"装置区人工打扫卫生、扫雪作业，装置区外草坪清理、浇灌等作业，现场检查（进入受限空间除外）"},{"key":"B","text":"操作规程、操作卡等规定的如：日常的生产工艺操作调整、化验、实验室取样及分析、操作生产区域的日常巡检活动，都按照相关的操作程序及管理规定进行的作业"},{"key":"C","text":"设备设施的供货厂家或服务方在现场调试或技术指导，由其提供规程或作业计划书，并由对口单位或部门同意的作业"},{"key":"D","text":"按指定路线现场参观"}],"answer":"ABCD","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0073","type":"判断题","question":"基层单位作业负责人对风险作业进行预约，没有预约的作业不得进行施工。抢修作业可当日预约。不涉及上报炼化板块的各等级作业预约由基层单位在网页或其他公用平台内公示。具体见附录C《公司风险作业预约管理要求》。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0074","type":"多选题","question":"在安全受控平台内作业预约必须注明项目名称、任务描述、（）、（）、主管部门、预约时间、作业地点、（）、（）、作业风险等内容。","options":[{"key":"A","text":"预约单位"},{"key":"B","text":"施工单位"},{"key":"C","text":"作业类型"},{"key":"D","text":"作业等级"}],"answer":"ABCD","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0075","type":"判断题","question":"作业所在车间的项目负责人、能量隔离作业构建人或能量隔离审批人根据已批准的能量许可证，到现场进行落实确认。经过审批、确认后的能量许可证由生产车间打印，附在作业许可证后，交施工单位实施。构建人与审批人可以是同一人。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"任何等级作业票，构建人与签发人（审批人）不得是同一人；题干称“可以是同一人”不正确。","subject":"作业风险评估许可证管理规定"},{"id":"0076","type":"单选题","question":"受限空间作业许可证有效期为（）：","options":[{"key":"A","text":"8小时"},{"key":"B","text":"一个班次"},{"key":"C","text":"72小时"},{"key":"D","text":"24小时"}],"answer":"D","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0077","type":"多选题","question":"一份完整的作业许可证包括（）","options":[{"key":"A","text":"《作业风险评估许可证》"},{"key":"B","text":"《作业许可证现场确认检查表》"},{"key":"C","text":"《能量隔离许可证》"},{"key":"D","text":"《作业计划书》"}],"answer":"ABC","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0078","type":"判断题","question":"作业许可证由授权签发人、基层单位项目作业负责人、安全管理人员和施工单位作业负责人到现场检查确认，相关人员填写《作业许可证现场确认检查表》。1、2级作业施工作业单位安排监护人员后，方可进行作业。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0079","type":"判断题","question":"3、4级作业生产单位和施工作业单位共同安排监护人员后，方可进行作业。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"作业风险评估许可证管理规定"},{"id":"0080","type":"单选题","question":"装置出现生产异常时，联合运行部当班值（班）长确认后，迅速（ ）向公司总调度室汇报，并及时汇报处置过程中关键步骤、主要操作调整内容及公用工程调整需求。","options":[{"key":"A","text":"2分钟内"},{"key":"B","text":"5分钟内"},{"key":"C","text":"8分钟内"},{"key":"D","text":"10分钟内"}],"answer":"B","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0081","type":"单选题","question":"当发生危险化学品泄漏、爆炸、重大人身伤亡、公用工程系统或异常中断等严重影响公司安全生产的事故事件，各单位( )内向公司总调度室汇报，汇报要尽量具体到时间、地点、影响范围、人员伤亡等情况。","options":[{"key":"A","text":"2分钟内"},{"key":"B","text":"5分钟内"},{"key":"C","text":"8分钟内"},{"key":"D","text":"10分钟内"}],"answer":"B","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0082","type":"单选题","question":"A、B类装置发生非计划停工快报，由直属单位在（）小时内报生产运行处，生产运行部负责36小时内报送炼化板块总调度室。","options":[{"key":"A","text":"24小时内"},{"key":"B","text":"32小时内"}],"answer":"B","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0083","type":"单选题","question":"A、B类装置非计划停工，在装置恢复正常生产（）天内直属单位和公司主管部门充分对接分析，按照模板完成“装置非计划停工报告”，报生产运行部，生产运行部负责两周内报炼化板块总调度室。","options":[{"key":"A","text":"12天内"},{"key":"B","text":"14天内"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0084","type":"判断题","question":"生产指令主要用于应急指挥、日常生产协调指挥，物料、公用工程平衡调整、一般生产方案调整等。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0085","type":"判断题","question":"生产指令在数字可视化平台下达，直属单位在数字可视化平台填写接收、执行情况，完成后要及时将执行情况反馈给公司总调度室。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0086","type":"判断题","question":"新建或经过重大技术改造后生产装置的开工，直属单位需提前15个工作日向公司生产运行部提交装置开工申请。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0087","type":"判断题","question":"生产操作变动执行《生产组织、指挥及操作变动监控管理规定》，一、二级操作变动，直属单位在生产装置恢复正常生产后及时开展技术分析，总结经验。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0088","type":"判断题","question":"调度令由公司领导或生产运行部负责人签发；","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0089","type":"判断题","question":"生产调度令下发后，调度令接受单位负责人必须无条件接受，并按生产调度令内容执行。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"生产汇报及信息传递管理规定"},{"id":"0090","type":"单选题","question":"( )负责公司应急管理的归口管理；负责协调组织制定公司应急管理相关制度，并对制度的执行进行监督检查和验证评价。","options":[{"key":"A","text":"办公室"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"B","explanation":"","subject":"应急管理规定"},{"id":"0091","type":"单选题","question":"（ )负责公司应急预案管理；负责公司应急演练管理；负责公司应急培训管理。","options":[{"key":"A","text":"办公室"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"C","explanation":"","subject":"应急管理规定"},{"id":"0092","type":"单选题","question":"（ ）负责建立公司应急专家库；负责公司应急物资总体管理。","options":[{"key":"A","text":"机动设备部"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"C","explanation":"","subject":"应急管理规定"},{"id":"0093","type":"单选题","question":"（ ）负责信息通讯类应急物资专业管理和公司通讯抢险应急队伍的建设。","options":[{"key":"A","text":"机动设备部"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"D","explanation":"","subject":"应急管理规定"},{"id":"0094","type":"单选题","question":"（ ）负责公司消防、气防、环保、医疗救护类应急物资专业管理和相关专业应急救援队伍建设。","options":[{"key":"A","text":"机动设备部"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"C","explanation":"","subject":"应急管理规定"},{"id":"0095","type":"单选题","question":"( )负责输转设备、特种车辆、事故电源、防雷击、带压堵漏类应急物资专业管理和带压堵漏应急队伍建设","options":[{"key":"A","text":"机动设备部"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0096","type":"单选题","question":"（ ）负责自然灾害类的应急物资专业管理。","options":[{"key":"A","text":"机动设备部"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"工程管理部"}],"answer":"D","explanation":"","subject":"应急管理规定"},{"id":"0097","type":"单选题","question":"炼化装置及罐区发生着火、爆炸事故时，事故发生1小时之内由（ ）向集团公司智能运营中心书面报告。","options":[{"key":"A","text":"办公室"},{"key":"B","text":"生产运行部"},{"key":"C","text":"质量健康安全环保部"},{"key":"D","text":"规划和科技信息部"}],"answer":"B","explanation":"","subject":"应急管理规定"},{"id":"0098","type":"判断题","question":"公司级、直属单位、联合运行部级应急预案每三年至少修订一次，车间（站、队、所）应急预案、联合运行部应急操作卡每年至少修订一次","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0099","type":"判断题","question":"各类最新有效纸质版本应急预案按照其内容和适用的范围发放到执行部门、单位和岗位。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0100","type":"判断题","question":"公司每半年至少组织一次公司级综合性应急演练，各级专业部门每年至少组织一次本专业负责编制的专项应急预案的演练；直属单位、联合运行部每半年至少组织一次应急演练；基层车间（站、队）每季度至少组织一次应急小组全员参加的应急演练；班组每月组织一次现场应急演练。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0101","type":"判断题","question":"应急演练过程应按照附录B要求建立演练记录，每次演练完成1周内应完成应急演练效果总结并报同级安全部门备案。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0102","type":"判断题","question":"车间（站、队、所）应急预案、联合运行部应急操作卡由各基层单位组织工艺、设备、安全环保、班组长、技师等岗位人员编制、修订，要落实一分钟应急要求，明确“第一时间报警、联锁启动、工艺隔离、设备停运、人员救助”关键顺序，强化基层的处置和拉动。直属单位、联合运行部相关专业审核，直属单位、联合运行部主管领导审批发布。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"应急管理规定"},{"id":"0103","type":"多选题","question":"以下属于生产性设备用火的包括（）。","options":[{"key":"A","text":"锅炉"},{"key":"B","text":"加热炉"},{"key":"C","text":"焚烧炉"},{"key":"D","text":"装置区检修设备使用电气焊"}],"answer":"ABC","explanation":"","subject":"动火作业安全管理规定"},{"id":"0104","type":"多选题","question":"以下属于特级动火作业的有（ ）。","options":[{"key":"A","text":"在火灾爆炸危险场所处于运行状态下的生产装置中，带有可燃、易爆、有毒等介质的设备、管线、储罐、容器及工业下水井、污水池等部位进行的动火作业（包括带压不置换动火）按特级动火处理"},{"key":"B","text":"存有易燃易爆介质的重大危险源罐区防火堤内的动火作业。"},{"key":"C","text":"安装有易燃填料凉水塔的用火作业（凉水塔整体、下部积水池围堰等区域以内）安装有易燃填料凉水塔的动火作业（凉水塔整体、下部积水池围堰等区域以内）属于特级动火作业"},{"key":"D","text":"其它特殊情况下的用火。"}],"answer":"ABCD","explanation":"","subject":"动火作业安全管理规定"},{"id":"0105","type":"多选题","question":"下列属于动火作业管理范围的包括（ ）。","options":[{"key":"A","text":"电焊、气焊、钎焊、塑料焊等各种焊接、切割作业"},{"key":"B","text":"电热处理、电钻、砂轮、风镐及破碎、锤击、爆破、黑色金属撞击等产生火花的作业"},{"key":"C","text":"生产装置、罐区、火车及汽车装卸台、液化气充装站、瓦斯站、加油站、系统管带、污油池、易燃易爆场所及危险物品仓库，连接临时电源、使用非防爆电气设备和非防爆工具（包括使用非防爆电钻、砂轮、风镐等）"},{"key":"D","text":"进入易燃易爆场所的机动车辆、燃油机械等设备"}],"answer":"ABCD","explanation":"","subject":"动火作业安全管理规定"},{"id":"0106","type":"单选题","question":"风险评估许可证（RAP）中特级作业有效时间不超过（）。","options":[{"key":"A","text":"12小时"},{"key":"B","text":"8小时"},{"key":"C","text":"24小时"},{"key":"D","text":"72小时"}],"answer":"B","explanation":"","subject":"动火作业安全管理规定"},{"id":"0107","type":"单选题","question":"装置停工大检修，通过装置停工验收合格后，并安全实施了第一次动火作业的装置内动火,动火作业有效时间不超过（）；","options":[{"key":"A","text":"24"},{"key":"B","text":"8"},{"key":"C","text":"72"},{"key":"D","text":"12"}],"answer":"C","explanation":"","subject":"动火作业安全管理规定"},{"id":"0108","type":"判断题","question":"特级、一级动火作业在作业前应由授权签发人、安全监督人员和施工单位负责人到现场填写《作业许可证现场确认检查表》，并由生产单位、施工单位安排监护人员后，方可进行作业。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"动火作业安全管理规定"},{"id":"0109","type":"单选题","question":"单位第一负责人及以上领导负责对()风险的用火作业进行作业许可签发。","options":[{"key":"A","text":"一级"},{"key":"B","text":"二级"},{"key":"C","text":"特级"}],"answer":"C","explanation":"","subject":"动火作业安全管理规定"},{"id":"0110","type":"判断题","question":"设备检、维修及施工作业中涉及特级风险的用火作业，由直属单位机动部门对车间项目负责人组织进行的风险评估内容和对电器设备、仪表设备以及射线装置等电隔离、仪表和射线隔离措施进行检查并签字确认。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"动火作业安全管理规定"},{"id":"0111","type":"单选题","question":"固定用火区域审批有效期为( )。","options":[{"key":"A","text":"半年"},{"key":"B","text":"一年"},{"key":"C","text":"三个月"},{"key":"D","text":"两年"}],"answer":"A","explanation":"","subject":"动火作业安全管理规定"},{"id":"0112","type":"多选题","question":"用火必须严格执行用火制度，做到“四不用火”，即：( )","options":[{"key":"A","text":"没有批准的作业风险评估许可作业票不用火"},{"key":"B","text":"没有防火措施或用火措施不落实不用火"},{"key":"C","text":"没有用火监护人不用火"},{"key":"D","text":"动火部位、动火时间与作业风险评估许可作业票不符不动火。"}],"answer":"ABCD","explanation":"","subject":"动火作业安全管理规定"},{"id":"0113","type":"单选题","question":"动火作业许可证是现场动火的依据，只限在指定的地点和时间范围内使用，不得涂改、代签。一张动火作业许可证只允许一处动火。一处动火是指在设备容器内、正在运行的甲类装置内、罐区防火堤内不超过（ ）范围，其余地方原则上不超过（ ）范围的动火。","options":[{"key":"A","text":"10米，12.5米"},{"key":"B","text":"30米，50米"},{"key":"C","text":"7.5米，15米"},{"key":"D","text":"12.5米，22.5米"}],"answer":"C","explanation":"","subject":"动火作业安全管理规定"},{"id":"0114","type":"单选题","question":"动火作业前，应对作业区域或动火点可燃气体浓度进行检测。应使用检定合格确定其处于正常工作状态，并经公司认可的便携式有毒有害检测仪或其他类似手段进行分析，被测的可燃气体或可燃液体蒸汽浓度应小于其与空气混合爆炸下限的( )。","options":[{"key":"A","text":"25%(LEL)"},{"key":"B","text":"10%(LEL)"},{"key":"C","text":"1%(V/V)"},{"key":"D","text":"5%(V/V)"}],"answer":"B","explanation":"","subject":"动火作业安全管理规定"},{"id":"0115","type":"单选题","question":"检测合格后超过( )分钟的用火，需重新采样检测，并将分析时间、数据在作业许可证现场确认批准表中注明。","options":[{"key":"A","text":"30"},{"key":"B","text":"60"},{"key":"C","text":"120"},{"key":"D","text":"15"}],"answer":"A","explanation":"","subject":"动火作业安全管理规定"},{"id":"0116","type":"单选题","question":"距用火点( )内所有的地漏、排水口、各类水封井、阀门井、排气管、管道、地沟等必须封严盖实。","options":[{"key":"A","text":"10米"},{"key":"B","text":"12.5米"},{"key":"C","text":"15米"},{"key":"D","text":"30米"}],"answer":"C","explanation":"","subject":"动火作业安全管理规定"},{"id":"0117","type":"单选题","question":"在用气焊（割）动火作业时，氧气瓶与乙炔气瓶间距应不小于( )，且乙炔气瓶严禁卧放，二者与动火作业地点均不小于( )，并不准在烈日下暴晒。","options":[{"key":"A","text":"10米，15米"},{"key":"B","text":"15米，30米"},{"key":"C","text":"12.5米，7.5米"},{"key":"D","text":"5米，10米"}],"answer":"D","explanation":"","subject":"动火作业安全管理规定"},{"id":"0118","type":"多选题","question":"各单位负责人的职责有（ ）：","options":[{"key":"A","text":"组织实施重大危险源安全监测监控体系建设，完善控制措施，保证安全监测监控系统符合国家标准或者行业标准的规定"},{"key":"B","text":"组织定期对安全设施和监测监控系统进行检测、检验，并进行经常性维护、保养，保证有效、可靠运行"},{"key":"C","text":"对于超过个人和社会可容许风险值限值标准的重大危险源，组织采取相应的降低风险措施，直至风险满足可容许风险标准要求"},{"key":"D","text":"组织审查涉及重大危险源的外来施工单位及人员的相关资质、安全管理等情况，审查涉及重大危险源的变更管理"}],"answer":"ABCD","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0119","type":"单选题","question":"新建、改建和扩建危险化学品建设项目，在设计阶段完成重大危险源的危险与可操作性分析（HAZOP），在建设项目竣工验收前完成重大危险源的辨识、分级、安全评估、登记建档工作，并向（）应急管理局备案。","options":[{"key":"A","text":"独山子区"},{"key":"B","text":"克拉玛依市"},{"key":"C","text":"集团公司"},{"key":"D","text":"自治区"}],"answer":"A","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0120","type":"多选题","question":"重大危险源配备（）、组份等信息的不间断采集和监测系统以及可燃气体和有毒有害气体泄漏检测报警装置，并具备信息远传、连续记录、事故预警、信息存储等功能；一级或者二级重大危险源，具备紧急停车功能。","options":[{"key":"A","text":"温度"},{"key":"B","text":"压力"},{"key":"C","text":"液位"},{"key":"D","text":"流量"}],"answer":"ABCD","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0121","type":"多选题","question":"重大危险源的化工生产装置装备满足安全生产要求的自动化控制系统；一级或者二级重大危险源，装备（）；对重大危险源中的毒性气体、剧毒液体和易燃气体等重点设施以及一级、二级重大危险源中的危险化学品罐区，设置（）；毒性气体的设施设置泄漏物（）。涉及毒性气体、液化气体、剧毒液体的一级或者二级重大危险源，配备独立的（）。","options":[{"key":"A","text":"紧急停车系统"},{"key":"B","text":"紧急切断装置"},{"key":"C","text":"紧急处置装置"},{"key":"D","text":"安全仪表系统（SIS）"}],"answer":"ABCD","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0122","type":"单选题","question":"重大危险源根据其危险程度，分为一级、二级、三级和四级，（）为最高级别。","options":[{"key":"A","text":"一级"},{"key":"B","text":"二级"},{"key":"C","text":"三级"},{"key":"D","text":"四级"}],"answer":"A","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0123","type":"多选题","question":"重大危险源现场设置安全包保公示牌，写明重大危险源的（）、（）、（）姓名、对应的安全包保职责及（），接受员工监督。","options":[{"key":"A","text":"主要负责人"},{"key":"B","text":"技术负责人"},{"key":"C","text":"操作负责人"},{"key":"D","text":"联系方式"}],"answer":"ABCD","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0124","type":"单选题","question":"重大危险源记录的电子数据的保存时间不少于（ ）天；","options":[{"key":"A","text":"15"},{"key":"B","text":"30"},{"key":"C","text":"60"},{"key":"D","text":"一年"}],"answer":"B","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0125","type":"单选题","question":"重大危险源的化工生产装置装备满足安全生产要求的自动化控制系统；（ ）级或者（ ）级重大危险源，装备紧急停车系统；","options":[{"key":"A","text":"特级、一级"},{"key":"B","text":"一级、二级"},{"key":"C","text":"二级、三级"},{"key":"D","text":"三级、四级"}],"answer":"B","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0126","type":"单选题","question":"危险化学品重大危险源档案的保存期限为（ ）年","options":[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"10"}],"answer":"D","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0127","type":"多选题","question":"各单位应当对辨识确认的重大危险源及时、逐项进行登记建档。重大危险源档案应当至少包括下列文件、资料（）：","options":[{"key":"A","text":"重大危险源基本特征表"},{"key":"B","text":"重大危险源安全管理规章制度及安全操作规程"},{"key":"C","text":"安全评估报告或者安全评价报告"},{"key":"D","text":"重大危险源场所安全警示标志的设置情况"}],"answer":"ABCD","explanation":"","subject":"危险化学品重大危险源管理规定"},{"id":"0128","type":"单选题","question":"做塔内、罐内取样分析时，第一个样必须用（）取，取样时人必须站在取样点的侧面和上风口，头不能伸进人孔内，要与人孔处保持一定安全距离。","options":[{"key":"A","text":"铜制的长杆"},{"key":"B","text":"铁制的长杆"},{"key":"C","text":"铜制的短杆"},{"key":"D","text":"铁制的短杆"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0129","type":"单选题","question":"受限空间作业办理程序具体执行《作业风险评估许可证管理规定》中规定的风险评估许可证（RAP）办理流程，作业有效时间为( )。","options":[{"key":"A","text":"8"},{"key":"B","text":"12"},{"key":"C","text":"不超过24小时"},{"key":"D","text":"一个班次"}],"answer":"C","explanation":"","subject":"受限空间作业管理规定"},{"id":"0130","type":"单选题","question":"（）为非常规受限空间作业。","options":[{"key":"A","text":"可燃气体或蒸汽浓度高于与空气混合物爆炸下限的4%的受限空间"},{"key":"B","text":"与受限空间相连的管线、阀门无法拆除或加盲板"},{"key":"C","text":"温度大于35℃的受限空间"},{"key":"D","text":"常规的厂房或库房"}],"answer":"B","explanation":"","subject":"受限空间作业管理规定"},{"id":"0131","type":"单选题","question":"受限空间作业照明应使用安全电压不大于( )V的安全行灯。","options":[{"key":"A","text":"36"},{"key":"B","text":"12"},{"key":"C","text":"24"},{"key":"D","text":"6"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0132","type":"多选题","question":"符合下列条件之一的围堤，可视为受限空间（）","options":[{"key":"A","text":"高于1.2m的垂直墙壁围堤，且围堤内外没有到顶部的台阶"},{"key":"B","text":"在围堤区域内，作业者身体暴露于物理或化学危害之中"},{"key":"C","text":"可能存在比空气重的有毒有害气体"},{"key":"D","text":"高于1.5m的垂直墙壁围堤，且围堤内外没有到顶部的台阶"}],"answer":"ABC","explanation":"","subject":"受限空间作业管理规定"},{"id":"0133","type":"多选题","question":"作业项目监护人职责包括（）","options":[{"key":"A","text":"属地单位及施工单位应指定专人监护，监护人不少于2人"},{"key":"B","text":"应在受限空间入口处进行全程监护，掌握作业人员情况并与其保持沟通，防止未经授权人员进入受限空间"},{"key":"C","text":"应对进出受限空间的人员及工器具种类、数量进行登记，检查作业人员个人气体防护器材、通讯设施、气体检测仪、安全绳等的佩戴使用情况"},{"key":"D","text":"在风险较大的受限空间作业时，应当增设监护人员，并随时与受限空间内作业人员保持联络。"}],"answer":"ABCD","explanation":"","subject":"受限空间作业管理规定"},{"id":"0134","type":"多选题","question":"符合下列条件之一的动土，可视为受限空间（）","options":[{"key":"A","text":"动土深度大于1.2m，或作业时人员的头部在地面以下的"},{"key":"B","text":"在动土区域内，身体处于物理或化学危害之中"},{"key":"C","text":"在动土区域内，可能存在比空气重的有毒有害气体"},{"key":"D","text":"在动土区域内，没有撤离通道的"}],"answer":"ABCD","explanation":"","subject":"受限空间作业管理规定"},{"id":"0135","type":"多选题","question":"下列属于受限空间安全隔离的为（）","options":[{"key":"A","text":"加盲板或拆除一段管道的方式进行隔离"},{"key":"B","text":"对可能危及安全作业的孔、洞应进行严密封堵"},{"key":"C","text":"对作业设备上的电器电源，采取可靠的断电措施，且上锁并加挂警示牌"},{"key":"D","text":"对放射源进行屏蔽处理"}],"answer":"ABCD","explanation":"","subject":"受限空间作业管理规定"},{"id":"0136","type":"多选题","question":"受限空间取样分析合格判定指标为()","options":[{"key":"A","text":"使用色谱分析时，当被测气体或蒸气的爆炸下限≥4%时，其被测浓度应不大于O.5%(体积分数)；当被测气体或蒸气的爆炸下限＜4%时，其被测浓度应不大于O.2%(体积分数)"},{"key":"B","text":"使用移动式可燃气体报警仪检测分析时，可燃气体或蒸汽浓度应小于其与空气混合物爆炸下限的10%（LEL），且应使用两台设备进行对比检测"},{"key":"C","text":"氧气含量在19.5～21％（体积分数），在富氧环境下不应大于 23.5%（体积分数）"},{"key":"D","text":"有毒有害气体允许浓度应当符合《工作场所有害因素职业接触限值 第1部分：化学有害因素》（GBZ 2.1）的规定"}],"answer":"ABCD","explanation":"","subject":"受限空间作业管理规定"},{"id":"0137","type":"判断题","question":"受限空间内气体检测的结果报出30分钟后，仍未开始作业，可不用重新进行检测。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"作业中断时间超过30分钟，应重新进行气体检测，并由作业人员、作业监护人重新确认安全条件，不能“不用重新检测”。","subject":"受限空间作业管理规定"},{"id":"0138","type":"判断题","question":"色谱分析必须用球胆取样，并多次置换干净后送化验室做分析。样品必须保留到作业结束为止，以便复查。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0139","type":"判断题","question":"受限空间检测要有代表性、全面性，在一般容器取样插入深度为1米以上；在较大容器中取样插入深度为3米以上；在各种气柜、储油罐、球罐中取样插入深度为4米以上。要对上、中、下（左、中、右）各部位分别检测，取样时应停止任何气体吹扫，测试次序应是氧含量、易燃易爆气体、有毒有害气体。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0140","type":"判断题","question":"一般受限空间图标（3级风险）：运行部的一般受限空间作业由作业所属单位专业助理工程师和安全助理工程师及以上会签，由二级工程师及以上人员审批签发。其他直属单位（如热电厂、机电仪运维中心、铁路运输公司等）一般受限空间作业由作业所属单位专业助理工程师和安全助理工程师及以上会签，由基层单位副主任工程师（二级工程师）及以上人员审批签发。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0141","type":"判断题","question":"特殊受限空间图标（4级风险）：运行部的特殊受限空间作业由所属专业二级工程师和安全工程师及以上人员会签，由单位二级正职及以上领导审批签发。其他直属单位（如热电厂、机电仪运维中心、铁路运输公司等）的特殊受限空间作业，由基层单位作业所属专业工程师、安全工程师及以上人员，会同直属单位对应专业部门人员会签，由直属单位专业主管领导审批签发。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"受限空间作业管理规定"},{"id":"0142","type":"判断题","question":"特殊受限空间以及超过3天的一般受限空间作业，应制定应急措施或应急预案，并开展应急演练，所有相关人员都应熟悉应急措施或应急预案。外部救援人员若参与企业救援活动，应具有相应的资质。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"应为特殊受限空间以及超过5天的一般受限空间作业制定应急措施或应急预案，不是超过3天。","subject":"受限空间作业管理规定"},{"id":"0143","type":"单选题","question":"各单位根据评审结果，需对巡检方案进行修订的，应按照规定流程重新审批，（ ）日内完成修订并通过网络、生产会等形式告知员工。","options":[{"key":"A","text":"30"},{"key":"B","text":"15"},{"key":"C","text":"10"}],"answer":"B","explanation":"","subject":"巡检管理规定"},{"id":"0144","type":"单选题","question":"各单位应保证巡检人员能够便捷查询到最新有效的巡检方案。巡检方案中各岗位巡检内容须具体、要求清晰，岗位人员能够熟练掌握（ ）。","options":[{"key":"A","text":"巡检方案"},{"key":"B","text":"检查标准"},{"key":"C","text":"领导要求"}],"answer":"B","explanation":"","subject":"巡检管理规定"},{"id":"0145","type":"判断题","question":"高点巡检是指装置（或系统）运行区域内相对孤立或人员达到较困难的塔器顶部、高处平台、罐顶、构架顶部平台或其他高点部位的巡回检查。各单位应在巡检方案中建立高点巡检清单，巡检频次、方式应以车间风险评价结果为依据合理设置，根据风险识别结果，可采用现场巡检、视频巡检或其他先进的巡检方式，也可以专业周检管理、消防设施检查等相结合，并结合实际设置相应的检查记录。高点巡检宜选择天气条件较好的白天进行，若因天气等特殊原因未执行巡检任务，应予以记录说明。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0146","type":"判断题","question":"各单位巡检方案内容要涵盖装置生产、系统管线管理、备（停）用设备设施、检维修服务、机柜间、变配电室、危化品、放射源、环保在线监测、水电汽公共基础设施、库房等生产经营事项以及法律法规及其他要求受控的服务与设施，应开展巡检。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0147","type":"判断题","question":"各单位根据生产操作、维护服务的特点，参照工艺技术规程、操作规程、工艺卡片、危害识别风险评价的结果等要求，按照闭环立体交叉巡检要求，系统设计单位领导、专业管理干部、值班干部、值班长（班长）、班组操作人员等岗位人员巡检站点，形成相互补充、各有侧重、相互监督的立体交叉巡检网络。巡检站点应全面覆盖装置高风险点（风险等级依据本单位危害因素台账中评价结果）、高点、边远等区域（包括长期停用设施、消防泡沫站、危化品库等），站点设置应确保巡检路线合理，并覆盖装置全部区域。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0148","type":"判断题","question":"装置操作人员现场巡检间隔不得大于2小时，涉及“两重点一重大”的生产、储存装置的操作服务人员现场巡检间隔不得大于1 小时，其他生产装置应根据生产特点明确巡检频次，所有生产装置巡检频次应满足法规的要求。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0149","type":"判断题","question":"巡检方案可以不按照模板编制","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"巡检方案必须按照模板编制（模板见制度附录B），不能自行不按模板编制。","subject":"巡检管理规定"},{"id":"0150","type":"判断题","question":"值班干部、值班长（班长）巡检每班次不少于1次；基层单位负责人、主管生产工艺、设备、安全的专业主管领导，工作日期间每日到生产现场进行巡检；每站点不少于2人次（“两重点一重大”装置每站点至少涵盖工艺、设备专业）。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0151","type":"判断题","question":"每条巡检路线第一站开始时间不得超过规定时间±10分钟，员工巡检次数和时间执行正式审批的巡检方案。2点、10点、18点因与交接班时间重合可提前30分钟进行巡检。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0152","type":"单选题","question":"各单位应建立相应的表彰奖励机制，鼓励员工认真履职尽责，及时认真巡检，对于巡检认真及时发现隐患的员工，要及时通报表扬奖励，公司定期对巡检优秀员工进行评比表彰，对于发现隐患级别达到公司通报表扬、立功级别的，应及时上报申请，具体执行（）。","options":[{"key":"A","text":"工会要求"},{"key":"B","text":"安质环处要求"},{"key":"C","text":"《群众生产管理规定》"}],"answer":"C","explanation":"","subject":"巡检管理规定"},{"id":"0153","type":"判断题","question":"有系统管线巡检职能的基层单位，应把巡检要求在巡检方案中明确规定，具体执行《公用工程及物料系统管理规定》。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0154","type":"判断题","question":"检维修服务单位工作日内，单位专业管理人员巡检不少于1人次/站点•天，班长和班组技术人员工作日内巡检不少于1人次/站点•天，操作服务人员应每日（节假日、双休日可结合实际情况制定）对维护区域开展维护巡检。公司级关键机组设备纳入四方联检管理，生产单位、钳工、电气、仪表应明确巡检项目及完好标准，每日巡检1次。各岗位巡检频次不低于《石油化工设备维护检修规程》要求。维保单位参照执行，具体执行巡检方案。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0155","type":"判断题","question":"后勤服务单位巡检可以不编制巡检方案","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"后勤服务单位也应根据本单位安全生产经营特点制定巡检方案，明确各岗位巡检范围、频次等内容，不能不编制。","subject":"巡检管理规定"},{"id":"0156","type":"判断题","question":"各单位巡检方案应明确规定岗位员工在巡检时应携带的巡检工具和测试仪器，携带的工具不应衍生妨碍自身在巡检路线上正常行走、攀爬直梯等安全隐患。巡检过程应保持通讯畅通。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0157","type":"判断题","question":"各单位要分级建立对各岗位人员巡检制度执行情况的检查、抽检、讲评机制，采取视频抽检、现场检查等方式，检查要做到对领导干部巡检、值班干部巡检、班组岗位巡检全覆盖，从严管理，每季度开展一次专项讲评；冬百活动期间和敏感时段、公司特殊要求期间按通知要求增加检查频次和讲评次数；公司生产运行部每年至少开展一次巡检管理专项讲评分析。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0158","type":"判断题","question":"各单位巡检方案应征求班组意见，并由单位专业负责人组织相关专业管理人员讨论，单位巡检方案发布及变更必须组织单位领导、安全、生产工艺、设备、综合专业审核会签。涉及“两重点一重大”的生产、储存装置单位的巡检方案，经过单位内部评审会签后，方案及会签表电子版交公司生产运行部、机动设备部、健康质量安全环保部备案。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0159","type":"判断题","question":"检维修服务单位（信息网络公司、供水供电公司、设备检修公司等）的巡检方案由单位负责人组织各专业管理人员、维护班组讨论，定稿后报属地单位会签，报公司机动设备部、生产运行部备案。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0160","type":"判断题","question":"各单位巡检方案应征求班组意见，并由单位专业负责人组织相关专业管理人员讨论，单位巡检方案发布及变更必须组织单位领导、安全、生产工艺、设备、综合专业审核会签。涉及“两重点一重大”的生产、储存装置单位的巡检方案，经过单位内部评审会签后，方案及会签表电子版5个工作日内上传公司巡检管理平台。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0161","type":"判断题","question":"各单位巡检方案变更及换版，必须在实施前及时以多种形式上进行培训宣贯，并保留培训记录。单位现行有效的巡检方案必须便于员工学习查询。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0162","type":"判断题","question":"巡检方案内容应至少包括以下几方面： a) 单位领导、专业管理干部、值班干部、值班长（班长）、班组操作人员等岗位员工的巡检频次、站点时间、路线等要求，巡检时保障质量、安全的通用要求及属地特殊要求； b) 各站点的检查内容与该点安全风险提示； c)单位领导、专业管理干部、值班干部、值班长（班长）、班组操作人员等岗位员工巡检路线图，班组操作人员每次巡检最优时间，属地有特殊性要求的应重点明确； d) 发现隐患的汇报程序及处理要求； e）高点巡检清单。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"巡检管理规定"},{"id":"0163","type":"单选题","question":"单位的（ ）是本单位的消防安全责任人，负责本单位消防安全的全面管理。","options":[{"key":"A","text":"安全总监"},{"key":"B","text":"主要负责人"},{"key":"C","text":"安全管理人员"},{"key":"D","text":"兼职消防安全管理人员"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0164","type":"单选题","question":"每名员工应当至少每年进行（ ）次消防安全培训。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0165","type":"单选题","question":"冬季雪后（ ）小时内，消防栓、消防炮、消防水鹤、消防阀井、消防栓箱、水泵接合器、消防竖管底层接口、手动报警按钮、灭火器等周围的积雪应清扫干净。","options":[{"key":"A","text":"12"},{"key":"B","text":"24"},{"key":"C","text":"48"},{"key":"D","text":"72"}],"answer":"C","explanation":"","subject":"消防安全管理规定"},{"id":"0166","type":"单选题","question":"消防管网应按照设计要求运行，稳高压消防给水系统压力应保持在0.7—1.2MPa。其他场所采用低压消防给水系统的系统工作压力应大于或等于( )MPa（自地面算起）。","options":[{"key":"A","text":"0.15"},{"key":"B","text":"0.6"},{"key":"C","text":"0.7"},{"key":"D","text":"1.2"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0167","type":"单选题","question":"消防设施、消防器材使用后( )小时内应及时恢复完好。","options":[{"key":"A","text":"12"},{"key":"B","text":"24"},{"key":"C","text":"48"},{"key":"D","text":"72"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0168","type":"单选题","question":"消防控制室管理应实行每日24 小时专人值班制度，每班不应少于( )人，每班工作时间不宜超过8小时。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0169","type":"单选题","question":"7、独山子石化公司企业火灾报警电话为( )，设置在公司消防内保支队火灾报警指挥中心，24小时值班运行。","options":[{"key":"A","text":"119"},{"key":"B","text":"3865119"},{"key":"C","text":"120"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0170","type":"单选题","question":"各单位在组织和指挥火灾现场扑救时,应及时设立应急指挥部,由单位（ ）或上级负责人任总指挥。","options":[{"key":"A","text":"安全总监"},{"key":"B","text":"主要负责人"},{"key":"C","text":"安全管理人员"},{"key":"D","text":"兼职消防安全管理人员"}],"answer":"B","explanation":"","subject":"消防安全管理规定"},{"id":"0171","type":"单选题","question":"消防水泵房（站）及其配电室应设应急照明或事故照明，其连续供电时间不少于（ ）小时。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"}],"answer":"C","explanation":"","subject":"消防安全管理规定"},{"id":"0172","type":"单选题","question":"10、厂外办公区灭火器每月进行一次检查。公司其它区域灭火器每（ ）进行一次检查。","options":[{"key":"A","text":"一季度"},{"key":"B","text":"一个月"},{"key":"C","text":"半月"}],"answer":"C","explanation":"","subject":"消防安全管理规定"},{"id":"0173","type":"判断题","question":"只设置有火灾自动报警系统的单位，依照自治区《建筑消防设施“三化”达标验收标准》规定，专兼职自动消防设施操作人员必须经过培训，至少有2人持证上岗。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"只设火灾自动报警系统的单位，专兼职自动消防设施操作人员至少有1人持证上岗即可，不是至少2人。","subject":"消防安全管理规定"},{"id":"0174","type":"判断题","question":"低压和临时高压消防系统消防水泵能在接到火灾报警后3分钟内投入运行，稳高压消防给水系统的消防水泵应为自动控制。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"低压和临时高压消防系统消防水泵应在接到火灾报警后2分钟内投入运行，不是3分钟；稳高压系统为自动控制是正确的。","subject":"消防安全管理规定"},{"id":"0175","type":"判断题","question":"消防车道、涉及公共消防安全的疏散设施和其他建筑消防设施应当由属地责任单位或者委托管理的单位统一管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0176","type":"判断题","question":"在火灾隐患未消除之前，单位应当落实防范措施，保障消防安全。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0177","type":"判断题","question":"“预防为主，防消结合”是消防工作方针。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0178","type":"判断题","question":"公司应当每半年、直属单位、联合运行部每月、联合车间（站、队）每周至少对重点部位进行一次常规消防安全检查。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0179","type":"判断题","question":"电动汽车、电动自行车（不包括生产专用叉车）。严禁停放在室内，严禁进入装置区域，可以在厂内、办公室进行充电。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"电动汽车、电动自行车严禁在室内（包括办公室）、装置区域、防爆区域充电，应在专用充电场所充电；题干称可在厂内、办公室充电不正确。","subject":"消防安全管理规定"},{"id":"0180","type":"判断题","question":"消防水泵应每周手动启动运转一次，并应检查供电电源的情况。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"消防水泵应每月手动启动运转一次并检查供电电源；每周应模拟自动控制条件自动启动运转一次，不是每周手动启动。","subject":"消防安全管理规定"},{"id":"0181","type":"判断题","question":"灭火器配置场所内的灭火器不应少于２具。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"消防安全管理规定"},{"id":"0182","type":"判断题","question":"寒冷季节，消防储水设备的任何部位均不得结冰。每天应检查设置储水设备的房间，保持室温不低于15℃。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"寒冷季节应保持储水设备房间室温不低于10℃，不是15℃。","subject":"消防安全管理规定"},{"id":"0183","type":"多选题","question":"管线打开实行作业许可，作业（属地）单位根据作业内容选择并执行()、（）、（）、（）","options":[{"key":"A","text":"生产装置操作规程或生产装置操作卡"},{"key":"B","text":"经分厂审批的专业维护作业票或动作卡"},{"key":"C","text":"RAP票"},{"key":"D","text":"《管线打开许可证》"}],"answer":"ABCD","explanation":"","subject":"管线打开作业管理规定"},{"id":"0184","type":"多选题","question":"管线打开工作交接的双方共同确认施工方案、风险识别与评估及防范措施、应急预案或作业计划书的工作内容、安全方案和相应措施，至少包括()、()、（）（）、（）","options":[{"key":"A","text":"有关安全、健康和环境方面的影响"},{"key":"B","text":"隔离位置、清理和确认清理合格的方法"},{"key":"C","text":"管线(设备)状况"},{"key":"D","text":"管线(设备)中残留的物料及危害等"},{"key":"E","text":"气体检测、分析"}],"answer":"ABCDE","explanation":"","subject":"管线打开作业管理规定"},{"id":"0185","type":"单选题","question":"作业前作业方案应与()沟通，并进行培训，所有相关人员熟悉作业内容与相关的风险要素及防范控制措施。","options":[{"key":"A","text":"施工人员"},{"key":"B","text":"监护人员"},{"key":"C","text":"所有相关人员"},{"key":"D","text":"属地单位人员"}],"answer":"C","explanation":"","subject":"管线打开作业管理规定"},{"id":"0186","type":"单选题","question":"当管线打开时间需超过（）个班次才能完成时应在交接班记录中予以明确。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0187","type":"单选题","question":"（）打开后不能及时恢复的，设备人孔处应悬挂禁入警示牌，对管口应进行封口，防止杂物进入。","options":[{"key":"A","text":"设备、管线"},{"key":"B","text":"设备、设施"},{"key":"C","text":"设施、管线"},{"key":"D","text":"设施、管口"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0188","type":"判断题","question":"根据管线打开作业的内容，办理《管线打开许可证》时，由管线打开作业单位的负责人申请，并提供如下相关资料和设施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"办理《管线打开许可证》时，应由管线打开作业单位的现场负责人申请并提供相关资料和设施，不是单位负责人。","subject":"管线打开作业管理规定"},{"id":"0189","type":"判断题","question":"明确管线打开的具体位置，在受管线打开影响的区域设置路障或警戒线，控制无关人员进入。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0190","type":"判断题","question":"管线打开过程中发现现场工作条件与安全工作方案不一致时(如导淋阀堵塞或管线清理不合格)，应停止作业，并进行再评估，重新制定安全工作方案，办理相关作业许可证。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0191","type":"判断题","question":"直属单位、维护单位或承包商的相关人员在工作交接时应对交接记录签字确认。拆除法兰螺栓时要以对角方位缓慢松开，防止管道内余压或残余物料喷出。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0192","type":"判断题","question":"当设备、管线打开时间需超过一个班次才能完成时应在交接班记录中予以明确，将该工作内容移交到接班班组。设备、管线打开后不能及时恢复的，设备人孔处应悬挂禁入警示牌，对管口应进行封口，防止杂物进入。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0193","type":"判断题","question":"管线打开作业时应根据作业风险选择和使用的个人防护装备，专业人员和使用人员应参与个人防护装备的选择。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0194","type":"判断题","question":"在释放或隔离能量前，应先观察压力表或液面计等仪表处于完好工作状态；通过观察压力表、视镜、液面计、低点导淋、高点放空等多种方式，综合确认贮存的能量已被彻底去除或已有效地隔离。设备本体温度应降低到符合检修要求。在确认过程中，应避免产生其他的危害。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"管线打开作业管理规定"},{"id":"0195","type":"多选题","question":"联锁分为( )和( )。","options":[{"key":"A","text":"工艺联锁"},{"key":"B","text":"设备联锁"},{"key":"C","text":"安全联锁"}],"answer":"AB","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0196","type":"单选题","question":"（）是公司联锁系统的归口管理部门。","options":[{"key":"A","text":"企管法规处"},{"key":"B","text":"安全质量处"},{"key":"C","text":"科技信息处"},{"key":"D","text":"机动设备处"}],"answer":"D","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0197","type":"单选题","question":"（）是工艺联锁的管理部门。","options":[{"key":"A","text":"企管法规处"},{"key":"B","text":"安全质量处"},{"key":"C","text":"科技信息处"},{"key":"D","text":"机动设备处"}],"answer":"C","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0198","type":"单选题","question":"（）是设备报警管理的管理部门。","options":[{"key":"A","text":"科技信息处"},{"key":"B","text":"机动设备处"},{"key":"C","text":"直属单位"},{"key":"D","text":"信息网络公司"}],"answer":"B","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0199","type":"单选题","question":"（）是工艺报警管理的管理部门。","options":[{"key":"A","text":"科技信息处"},{"key":"B","text":"机动设备处"},{"key":"C","text":"直属单位"},{"key":"D","text":"信息网络公司"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0200","type":"单选题","question":"（）是仪表报警、电气报警管理的管理部门。","options":[{"key":"A","text":"科技信息处"},{"key":"B","text":"机动设备处"},{"key":"C","text":"直属单位"},{"key":"D","text":"信息网络公司"}],"answer":"B","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0201","type":"单选题","question":"（）负责联锁变更的安全环保评价及安全环保预案审核","options":[{"key":"A","text":"直属单位生产运行部门"},{"key":"B","text":"直属单位安全部门"},{"key":"C","text":"直属单位机动部门"},{"key":"D","text":"直属单位技术部门"}],"answer":"B","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0202","type":"判断题","question":"直属单位生产运行部门需对本单位的联锁保护逻辑图和联锁台账进行审核。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0203","type":"判断题","question":"公司级专家组负责对联锁的长期摘除、撤销进行评估审批。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"公司级专家组只负责A类联锁的长期摘除、撤销进行评估审批，不是所有联锁。","subject":"联锁保护系统管理规定"},{"id":"0204","type":"判断题","question":"联锁分A、B、C三类管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"联锁分为A、B两级管理，不是A、B、C三类。","subject":"联锁保护系统管理规定"},{"id":"0205","type":"判断题","question":"联锁回路中报警值应在报警台帐中管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"联锁回路中的报警值（联锁报警值）应按制度6.4要求管理，由直属单位根据调校记录同步修订联锁台账和报警台账，不能只放在报警台账。","subject":"联锁保护系统管理规定"},{"id":"0206","type":"判断题","question":"工艺报警分A、B两类管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0207","type":"判断题","question":"所有联锁保护系统所用器件（包括一次元件）、仪表、设备，随装置停工大修时进行校验。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"联锁保护系统所用器件、仪表、设备原则随装置停工大修时校验，具备安全功能并单独制定保养维护检修策略的除外，不是“所有一律随大修校验”。","subject":"联锁保护系统管理规定"},{"id":"0208","type":"判断题","question":"在办理长期联锁工作票审批期间，可以暂时续签短期联锁票至长期联锁工作票办理完毕为止。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0209","type":"判断题","question":"具有安全功能联锁长期摘除不超过1个月，停运超过一个月的应重新办理长期联锁工作票。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0210","type":"判断题","question":"信息网络公司负责生产装置（系统）仪表、电气报警管理","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"仪表、电气报警管理由机动设备处和直属单位负责，科技信息处负责工艺报警管理；信息网络公司/维护单位只负责维护范围内报警设置及变更的实施、维护，不是其单独负责报警管理。","subject":"联锁保护系统管理规定"},{"id":"0211","type":"多选题","question":"联锁A、B类的划分应由直属单位与维护单位主管领导共同确认，报（）、（）及直属单位主管领导审批。","options":[{"key":"A","text":"直属单位生产运行部门"},{"key":"B","text":"直属单位安全部门"},{"key":"C","text":"直属单位机动部门"},{"key":"D","text":"直属单位技术部门"}],"answer":"CD","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0212","type":"多选题","question":"新（改扩）装置的联锁逻辑图由直属单位技术人员组织维护单位根据设计资料、软件组态资料编制，报直属单位机动部门、技术部门、（）和（）共同审核后报直属单位主管领导审批，由直属单位机动部门组织在装置开工前印刷出版。","options":[{"key":"A","text":"科技信息处"},{"key":"B","text":"机动设备处"},{"key":"C","text":"直属单位生产运行部门"},{"key":"D","text":"直属单位安全部门"}],"answer":"CD","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0213","type":"多选题","question":"维护人员在维护联锁保护系统时，应办理（）和（），并由生产装置人员监护作业。","options":[{"key":"A","text":"工作联络单"},{"key":"B","text":"联锁工作票"},{"key":"C","text":"检修工作票"}],"answer":"BC","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0214","type":"多选题","question":"A级工艺报警故障（）、B级工艺报警故障（）不能正常投用，直属单位应制定安全预案并汇报给技术管理部门协调解决。","options":[{"key":"A","text":"4小时"},{"key":"B","text":"8小时"},{"key":"C","text":"12小时"},{"key":"D","text":"24小时"}],"answer":"BD","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0215","type":"多选题","question":"报警要建立台账进行管理，明确（）和（）（）和（）报警。","options":[{"key":"A","text":"工艺"},{"key":"B","text":"设备"},{"key":"C","text":"仪表"},{"key":"D","text":"电气"}],"answer":"ABCD","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0216","type":"判断题","question":"设备报警确认后，直属根据报警原因，制订相应的检维修方案并组织实施，应保证设备运行参数在至报警指标范围内，不具备条件整改的制订应急预案，纳入缺陷隐患管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0217","type":"单选题","question":"联锁摘除时间在（）内为短期摘除。","options":[{"key":"A","text":"8小时"},{"key":"B","text":"24小时"},{"key":"C","text":"48小时"},{"key":"D","text":"72小时"}],"answer":"D","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0218","type":"判断题","question":"对联锁保护系统回路硬件进行技术改造时，应由维护单位提出。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"对联锁保护系统回路硬件进行技术改造时，应由发起方与相关单位相互配合出具方案（设备变更），报直属单位审核、主管领导批准后实施；不是由维护单位提出。","subject":"联锁保护系统管理规定"},{"id":"0219","type":"判断题","question":"对联锁保护系统回路的联锁值和报警值等参数、逻辑关系进行变更的，应由直属单位提出。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0220","type":"判断题","question":"A类联锁回路变更应报机动设备处或科技信息处备案.","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0221","type":"判断题","question":"由于工艺或设备原因需要长期摘除的联锁保护系统回路，应由直属单位提出申请（包括安全环保评价及安全环保预案）并填写长期联锁工作票.","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0222","type":"判断题","question":"停运超过一年的联锁保护系统，应每年重新办理长期联锁工作票。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"具有安全功能的联锁长期摘除不超过1个月，停运超过一个月的应重新办理长期联锁工作票，不是停运超过一年后每年办理。","subject":"联锁保护系统管理规定"},{"id":"0223","type":"判断题","question":"装置停工大修后再开工时所有摘除联锁应自动恢复投用，如需摘除应重新办理工作票。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0224","type":"判断题","question":"A级工艺报警值的变更应书面报直属单位技术部门审批后方可实施","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0225","type":"判断题","question":"B级工艺报警值的变更应由直属单位领导或主任批准后实施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0226","type":"判断题","question":"维护人员在维护报警时，可不办理检修工作票","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"维护人员在维护联锁保护系统（含报警）时，应办理联锁工作票和检修工作票，并由生产装置人员监护作业，不能不办理检修工作票。","subject":"联锁保护系统管理规定"},{"id":"0227","type":"判断题","question":"工艺、设备联动相关的回路、机构进行检修后，具备联调试验条件的必须进行联动试验，并做好相关记录。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0228","type":"判断题","question":"联锁、联动、报警回路（值）发生新增、撤销、变更的，直属单位、维护单位应组织员工完成变更培训工作。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0229","type":"判断题","question":"联动撤消、增加、变更必须进行仔细论证和充分评估后，由直属单位提出申请，经相应的工艺、设备、安全专业、主管领导审批后实施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"联锁保护系统管理规定"},{"id":"0230","type":"判断题","question":"生产运行部负责检维修及施工作业前生产装置、系统管线工艺处置方案审核及能量隔离管理，负责工艺能量隔离锁具使用、上锁挂签的监督管理。 负责制定盲板管理具体内容；负责装置物料、系统管线盲板和防互窜管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0231","type":"判断题","question":"机动设备部负责检维修及施工作业前电气、仪表、辐射能量隔离管理；负责电气、仪表、辐射隔离锁具使用、上锁挂签的监督管理。 负责盲板及盲板垫片的材质和规格使用的监督管理。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0232","type":"多选题","question":"能量隔离的类型包括:（ ）。","options":[{"key":"A","text":"电气隔离，如断开开关，拉开关闸刀等，包括必要的测试及上锁挂签"},{"key":"B","text":"工艺隔离，如阀门的开启和关闭及上锁挂签等"},{"key":"C","text":"机械隔离，如加装盲板"},{"key":"D","text":"仪表隔离，如联锁摘除、切断仪表动力源等"},{"key":"E","text":"辐射隔离，如隔离、关闭辐射源及设置警戒区域。"}],"answer":"ABCDE","explanation":"","subject":"能量隔离管理规定"},{"id":"0233","type":"单选题","question":"( )根据检维修施工作业需求选择电气隔离、工艺隔离、机械隔离、仪表隔离和辐射隔离措施。根据能量性质及隔离方式选择相匹配的断开、隔离设施，管线、设备的隔离执行《管线打开作业管理规定》，电气隔离执行相关标准与规定。","options":[{"key":"A","text":"属地单位作业人员"},{"key":"B","text":"施工作业人员"},{"key":"C","text":"施工单位检修项目负责人"},{"key":"D","text":"基层单位项目负责人"}],"answer":"D","explanation":"","subject":"能量隔离管理规定"},{"id":"0234","type":"判断题","question":"RAP许可证系统不能正常运行时，涉及盲板抽堵作业的，须办理《盲板抽堵作业票》（见附表A.4）。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0235","type":"判断题","question":"隔离措施必须到现场检查确认，相关责任人员签字后，方能签发（电子签字或在需要条件下由专业授权人员手动签字）能量隔离许可证，与相应作业许可证进行关联。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0236","type":"判断题","question":"能量隔离（EIP）执行的原则：隔离措施未执行到位，不能确认隔离状态，不得签发关联的作业许可证；作业完成之前不能解除隔离。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0237","type":"判断题","question":"上锁挂签由基层单位项目负责人组织完成，检修作业完成后由项目负责人牵头组织完成解锁、拆签。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0238","type":"判断题","question":"锁具柜内锁具、钥匙、标签等只能用于施工检维修能量隔离，不得用于其他目的如安保防盗。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0239","type":"判断题","question":"所有锁具的备用钥匙由基层单位指定专人保管。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0240","type":"单选题","question":"能量隔离、上锁、挂标签的步骤：( )。","options":[{"key":"A","text":"隔离→测试、交底→上锁、挂签→确认→工作完成后解锁、拆签"},{"key":"B","text":"隔离→危害辨识→上锁、挂签→确认→测试、交底→工作完成后解锁、拆签"},{"key":"C","text":"危害辨识→隔离→上锁、挂签→确认→测试、交底→工作完成后解锁、拆签"},{"key":"D","text":"危害辨识→隔离→上锁、挂签→测试、交底→工作完成后解锁、拆签"}],"answer":"C","explanation":"","subject":"能量隔离管理规定"},{"id":"0241","type":"多选题","question":"单个隔离点的上锁。用公共安全锁在隔离点上锁、挂标签。经基层单位项目负责人现场确认隔离到位后，将公共安全锁钥匙放在集中锁箱内。 ( )在集中锁箱上分别上个人锁。涉及电气隔离时，由电气维护专业人员实施上锁、挂标签，钥匙交基层单位项目负责人放在集中锁箱内。","options":[{"key":"A","text":"施工方项目负责人"},{"key":"B","text":"基层单位项目负责人"},{"key":"C","text":"属地班组长"},{"key":"D","text":"班组人员"}],"answer":"AB","explanation":"","subject":"能量隔离管理规定"},{"id":"0242","type":"单选题","question":"对于多个隔离点的上锁,涉及多个施工单位同时作业时，每个( )都要在集体锁箱上上个人安全锁。","options":[{"key":"A","text":"基层单位项目负责人"},{"key":"B","text":"施工方项目负责人"},{"key":"C","text":"基层单位班组长"},{"key":"D","text":"作业人员"}],"answer":"B","explanation":"","subject":"能量隔离管理规定"},{"id":"0243","type":"判断题","question":"工作进行中，参与作业人员提出再测试确认要求时，应再测试、确认。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0244","type":"判断题","question":"解锁依据先解集中锁箱后解隔离点安全锁，先解锁后拆签的原则进行。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"能量隔离管理规定"},{"id":"0245","type":"单选题","question":"公司（ ）是生产装置开、停工的归口管理部门，负责组织对各直属单位提出的装置开停工申请进行审核，负责组织生产装置开停工方案的编制与审核,负责对装置的开停工时间进度进行监督。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量安全环保部"},{"key":"D","text":"计划经营部"}],"answer":"A","explanation":"","subject":"装置开停工管理规定"},{"id":"0246","type":"单选题","question":"公司（ ）负责组织相关专业对装置停工后进入检修前的条件进行检查验收。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量安全环保部"},{"key":"D","text":"计划经营部"}],"answer":"C","explanation":"","subject":"装置开停工管理规定"},{"id":"0247","type":"单选题","question":"（ ）类装置的停、开工（含PSSR）验收分别由质量健康安全环保部、生产运行部组织直属单位、公司相关专业部门进行验收，并签字确认。","options":[{"key":"A","text":"A类"},{"key":"B","text":"B类"},{"key":"C","text":"C类"},{"key":"D","text":"全部"}],"answer":"A","explanation":"","subject":"装置开停工管理规定"},{"id":"0248","type":"单选题","question":"B、C类装置、单元（局部）的停、开工（含PSSR）验收分别由（ ）安全专业、生产技术专业组织相关专业人员进行验收，并签字确认。节假日、敏感时期、特殊时段，均升级至公司级管理。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量安全环保部"},{"key":"D","text":"直属单位"}],"answer":"D","explanation":"","subject":"装置开停工管理规定"},{"id":"0249","type":"单选题","question":"（ ）在装置开工前应成立PSSR验收小组，组织小组成员开展检查验收，并签字确认，具体执行《投用前安全检查管理规定》相关要求。","options":[{"key":"A","text":"生产运行部"},{"key":"B","text":"机动设备部"},{"key":"C","text":"质量安全环保部"},{"key":"D","text":"直属单位"}],"answer":"D","explanation":"","subject":"装置开停工管理规定"},{"id":"0250","type":"单选题","question":"装置（ ）合格后，引入公用工程介质进行气密、置换等工作，达到开工条件后，向生产运行部提出开工验收申请。","options":[{"key":"A","text":"PSSR验收"},{"key":"B","text":"停工验收"},{"key":"C","text":"开工验收"},{"key":"D","text":"竣工验收"}],"answer":"A","explanation":"","subject":"装置开停工管理规定"},{"id":"0251","type":"多选题","question":"需停产达到（ ）个月以上的，必须立即向所在县(市、区)应急管理部门书面报告。复产时企业要组织专家进行现场审查和安全条件确认具备复产条件后，提前（ ）个工作日向县(市、区)应急管理部门提出书面复产报告，经核查同意后企业方可恢复生产。","options":[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"7"}],"answer":"AD","explanation":"","subject":"装置开停工管理规定"},{"id":"0252","type":"多选题","question":"装置在停工、复产前，按照以下时间要求向政府应急管理部门履行（ ）、（ ）手续。","options":[{"key":"A","text":"竣工"},{"key":"B","text":"停工"},{"key":"C","text":"开复工"},{"key":"D","text":"停产"}],"answer":"BC","explanation":"","subject":"装置开停工管理规定"},{"id":"0253","type":"多选题","question":"日常检维修，装置停产时间在（ ）个月（含）以内的，应当在停产、复产前（ ）个工作日内告知所在县(市、区)应急管理部门。","options":[{"key":"A","text":"1"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"7"}],"answer":"AC","explanation":"","subject":"装置开停工管理规定"},{"id":"0254","type":"判断题","question":"装置在紧急停工或循环状态下（没有组织检维修或施工），在恢复生产前，由各直属单位组织对开工条件进行确认，使用《装置紧急停工后开工确认表》（见附录K），具备开工条件后直接开工和生产恢复。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"具备开工条件后，各直属单位应向公司总调度室汇报，按公司总调度室的指令组织开工和生产恢复，不能直接开工。","subject":"装置开停工管理规定"},{"id":"0255","type":"判断题","question":"装置在紧急停工或循环状态下，如果发现设备、仪表、电器、环保等设施不完好，必须组织检维修或施工。检维修或施工完毕，在开工恢复生产前，必须使用《投用前安全检查表》（见附录C1、C2）对完成的检维修或施工项目进行检查验收。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"装置开停工管理规定"},{"id":"0256","type":"判断题","question":"根据项目规模、任务进度安排，PSSR验收可分阶段、分专业多次实施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"装置开停工管理规定"},{"id":"0257","type":"单选题","question":"负责了解前沿的润滑技术和油品的升级情况，（ ）至少对《润滑技术规范》修订一次。新修订的《润滑技术规范》需经公司机动部门及公司设备主管领导审批后发布实施。","options":[{"key":"A","text":"1年"},{"key":"B","text":"2年"},{"key":"C","text":"4年"},{"key":"D","text":"每个大修周期"}],"answer":"D","explanation":"","subject":"设备润滑管理规定"},{"id":"0258","type":"单选题","question":"（ ）负责编制本单位的润滑五定手册，负责提出有关润滑油方面的改进措施和革新方案，负责牵头各专业编制本单位设备润滑加脂操作技术要点，经直属单位审核后组织实施。","options":[{"key":"A","text":"公司机动设备部"},{"key":"B","text":"科技信息处"},{"key":"C","text":"物资采购部"},{"key":"D","text":"直属单位"}],"answer":"D","explanation":"","subject":"设备润滑管理规定"},{"id":"0259","type":"单选题","question":"油浴润滑方式的油位应保持在视镜窗口的1/2～2/3或（ ）的规定刻度。","options":[{"key":"A","text":"以往经验"},{"key":"B","text":"标尺"},{"key":"C","text":"技术人员"},{"key":"D","text":"车间"}],"answer":"B","explanation":"","subject":"设备润滑管理规定"},{"id":"0260","type":"多选题","question":"关键机组应（ ）进行一次常规分析，主要设备应每（ ）进行一次常规分析，其余磨损及润滑监测分析项目依据设备的运行状况和使用需求委托研究院实施，润滑油分析频次见附录C。","options":[{"key":"A","text":"每周"},{"key":"B","text":"每月"},{"key":"C","text":"每季度"},{"key":"D","text":"每年"}],"answer":"BC","explanation":"","subject":"设备润滑管理规定"},{"id":"0261","type":"单选题","question":"严格执行润滑“五定” 和（ ）。滤网应符合如下规定：汽轮机油、冷冻机油、压缩机油、车用油及粘度相近的油品一级滤网60目、二级滤网80目、三级滤网100目；汽缸油、齿轮油、全系统损耗用油及粘度相近的油品一级滤网40目、二级滤网60目、三级滤网80目；“三级过滤”的滤网不得混用、代用。","options":[{"key":"A","text":"无需过滤"},{"key":"B","text":"三级过滤"},{"key":"C","text":"四级过滤"},{"key":"D","text":"两级过滤"}],"answer":"B","explanation":"","subject":"设备润滑管理规定"},{"id":"0262","type":"多选题","question":"润滑油（脂）常规分析项目主要有( )、( )、( )、( ) 、杂质。","options":[{"key":"A","text":"粘度"},{"key":"B","text":"酸值"},{"key":"C","text":"闪点"},{"key":"D","text":"水份"}],"answer":"ABCD","explanation":"","subject":"设备润滑管理规定"},{"id":"0263","type":"多选题","question":"( )规定每台设备的润滑部位及加油点；( )规定每个加、换油点的责任人；( )规定每个加油点的润滑油品牌号；( )规定加、换油时间； ( )规定每次加、换油数量。","options":[{"key":"A","text":"定点"},{"key":"B","text":"定人"},{"key":"C","text":"定质"},{"key":"D","text":"定时"}],"answer":"ABCDE","explanation":"","subject":"设备润滑管理规定"},{"id":"0264","type":"多选题","question":"润滑油（脂）的（ ）、（ ）、（ ）等管理具体执行《物资储存及配送管理规定》。","options":[{"key":"A","text":"入库验收"},{"key":"B","text":"保管"},{"key":"C","text":"出库"}],"answer":"ABC","explanation":"","subject":"设备润滑管理规定"},{"id":"0265","type":"判断题","question":"具有独立润滑系统的机（泵）组的循环油箱应配备滤油设备并加强脱水检查，脱水频次根据设备具体情况自行规定。大型关键机组在前述基础上可采用在线滤油方式来保障在用油品质量及性能。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"设备润滑管理规定"},{"id":"0266","type":"判断题","question":"对首次投用的新设备添加油品时，应对润滑系统彻底检查、清理后，才能添加新的油（脂）。技术协议有明确约定或制造厂人员现场指导时，按约定内容或指导意见实施。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"设备润滑管理规定"},{"id":"0267","type":"判断题","question":"在用润滑油（脂）经目测检查，凡符合：外观颜色明显改变；乳化严重；变干变硬；有明显可见的固体颗粒等条件之一者，应更换新油（脂）。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"设备润滑管理规定"},{"id":"0268","type":"判断题","question":"当更换润滑油过滤器的滤芯制造商或过滤精度发生变更时，不需要办理办理审批。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"B","explanation":"采用强制润滑油的设备更换润滑油过滤器滤芯制造商或过滤精度发生变更时，必须办理变更审批，不是不需要审批。","subject":"设备润滑管理规定"},{"id":"0269","type":"单选题","question":"各属地单位、维护单位人员每日对蓄能器外观及投用情况进行检查，确认外观完好，接头无渗油，压力正常，阀门位置正确。运行期间每（）对蓄能器外观及投用情况进行一次检查确认并填写检查记录","options":[{"key":"A","text":"周"},{"key":"B","text":"月"},{"key":"C","text":"季"},{"key":"D","text":"年"}],"answer":"B","explanation":"","subject":"转动设备管理规定"},{"id":"0270","type":"单选题","question":"离心泵的选用按（）最新版执行。","options":[{"key":"A","text":"API610"},{"key":"B","text":"API614"},{"key":"C","text":"API617"},{"key":"D","text":"API618"}],"answer":"A","explanation":"","subject":"转动设备管理规定"},{"id":"0271","type":"单选题","question":"高危泵密封选型、方案配置应符合（）标准要求","options":[{"key":"A","text":"API 610"},{"key":"B","text":"API 614"},{"key":"C","text":"API 682"},{"key":"D","text":"API 692"}],"answer":"C","explanation":"","subject":"转动设备管理规定"},{"id":"0272","type":"单选题","question":"转动设备实施分级管理，执行( )。分级结果与现场实际出现偏差，应及时合理调整该设备的关键性因素，修订该设备关键性级别。","options":[{"key":"A","text":"《润滑管理规定》"},{"key":"B","text":"《关键机组管理规定》"},{"key":"C","text":"《检修管理规定》"},{"key":"D","text":"《设备设施管理规定》"}],"answer":"D","explanation":"","subject":"转动设备管理规定"},{"id":"0273","type":"单选题","question":"泵的设计选型阶段给定泵优先选用的工作区。此工作区位于所提供叶轮的最佳效率点流量的（）区间内。","options":[{"key":"B","text":"70%-120%"},{"key":"C","text":"80%-110%"},{"key":"D","text":"90%-110%"}],"answer":"B","explanation":"","subject":"转动设备管理规定"},{"id":"0274","type":"多选题","question":"高危泵主要包括三类（）（）（）。","options":[{"key":"A","text":"高温热油类"},{"key":"B","text":"轻烃类"},{"key":"C","text":"有毒有害类"},{"key":"D","text":"重油类"}],"answer":"ABC","explanation":"","subject":"转动设备管理规定"},{"id":"0275","type":"多选题","question":"泵的特护管理，包括以下：","options":[{"key":"A","text":"振动速度值进入C区机泵"},{"key":"B","text":"故障频率高且未彻底消除的机泵"},{"key":"C","text":"切换后运行8小时内的机泵"},{"key":"D","text":"检修后第一次运行72小时内的机泵"}],"answer":"ABCD","explanation":"","subject":"转动设备管理规定"},{"id":"0276","type":"多选题","question":"转动设备的检修策略要以可靠性（RCM）为中心，以（）、（）、（）方式相结合，维修策略的制定要考虑设备运行的可靠性、经济性，既要防止失修，又要避免过修","options":[{"key":"A","text":"预防性检修"},{"key":"B","text":"预知性检修"},{"key":"C","text":"故障检修"},{"key":"D","text":"计划性检修"}],"answer":"ABC","explanation":"","subject":"转动设备管理规定"},{"id":"0277","type":"判断题","question":"对轴承箱密封处可能存在泄漏的部位应设置可靠的接油措施，并用管道或其他设施将泄漏的润滑油引至安全排放口，如使用管道引流，则应定期对管线的畅通情况进行检查，以防止管线堵塞造成润滑油聚集。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备管理规定"},{"id":"0278","type":"判断题","question":"汽轮机的保温衣应覆盖高温表面，包括仪表接管及阀门，如发现润滑油浸润时，必须及时更换。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备管理规定"},{"id":"0279","type":"判断题","question":"单台转动设备在7日内发生2次及以上检修为重复检修。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":"A","explanation":"","subject":"转动设备管理规定"},{"id":"0280","type":"多选题","question":"直属单位职责有（ ）：","options":[{"key":"A","text":"负责本单位风险分级防控和隐患排查治理工作的监督管理"},{"key":"B","text":"负责组织开展危害辨识、风险评价与防控"},{"key":"C","text":"负责本单位专业内隐患的查找识别、评价、申报、治理整改、验收和效果验证、控制应急等全过程的管理"},{"key":"D","text":"负责本单位专业内隐患的查找识别、评价、申报、治理整改、验收和效果验证、控制应急等全过程的管理"}],"answer":"ABCD","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0281","type":"单选题","question":"（）负责公司双重预防信息系统使用的监督检查；负责四级风险的收集、组织审核；负责牵头组织审核直属单位级以上事故隐患，建立公司事故隐患治理台帐，督促隐患治理工作，协调各部门事故隐患排查治理工作中的重大问题。","options":[{"key":"A","text":"安全质量环保处"},{"key":"B","text":"机动设备处"},{"key":"C","text":"生产运行处"},{"key":"D","text":"规划计划处"}],"answer":"A","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0282","type":"多选题","question":"风险隐患辨识方法有（）：","options":[{"key":"A","text":"工作前安全分析（JSA）"},{"key":"B","text":"工作危害分析（JHA）"},{"key":"C","text":"故障类型和影响分析（FMEA）"},{"key":"D","text":"安全完整性等级（SIL）危险和可操作性分析（HAZOP）"}],"answer":"ABCD","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0283","type":"多选题","question":"评价分级为（）、（）、（）、（）四个等级。一、二级风险为可接受风险，不需要采取进一步措施，但二级风险应保证控制措施的落实，可根据成本情况进行改进。三、四级风险为不可接受风险，必须制定进一步的增补风险削减措施，将风险降至一级或二级。","options":[{"key":"A","text":"一级风险（蓝色）"},{"key":"B","text":"二级风险（黄色）"},{"key":"C","text":"三级风险（橙色）"},{"key":"D","text":"四级风险（红色）"}],"answer":"ABCD","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0284","type":"单选题","question":"所有已识别的一、二级及以上风险都应有相应风险控制措施，对于风险为（）及以上的风险，必须制定硬件上的增补措施来降低风险至二级及以下，不得仅靠制定管理上的措施来降低风险等级。","options":[{"key":"A","text":"一级"},{"key":"B","text":"二级"},{"key":"C","text":"三级"},{"key":"D","text":"四级"}],"answer":"C","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0285","type":"多选题","question":"各单位安全环保事故隐患排查工作应当与（）、（）、（）、节前检查、（）等工作相结合。","options":[{"key":"A","text":"日常检查"},{"key":"B","text":"专项检查"},{"key":"C","text":"专业检查"},{"key":"D","text":"体系审核"}],"answer":"ABCD","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0286","type":"单选题","question":"风险隐患排查频次：装置操作人员现场巡检间隔不得大于2小时，涉及“两重点一重大”的生产、储存装置和部位的操作人员现场巡检间隔不得大于（）小时 ；","options":[{"key":"A","text":"0.5"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"3"}],"answer":"B","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0287","type":"单选题","question":"在役装置首次进行HAZOP分析后，原则上每（）年进行一次HAZOP分析，对于发生过多次工艺安全事故或进行过重大变更的装置，重新进行一次HAZOP分析。","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":"C","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0288","type":"单选题","question":"各部门、各单位每季度要对风险管理台帐组织评审，对风险防控措施有效性进行再评价，留下评审记录（附件D），更新风险管理台帐，在每季度第一个月的第（）个工作日前完成，发现风险防控措施缺失、失效的，及时纳入事故隐患治理台账管理。","options":[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"8"},{"key":"D","text":"10"}],"answer":"B","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0289","type":"多选题","question":"当出现以下何种情形时，公司及所属单位应当及时组织危害辨识、风险评估，隐患排查，更新风险管理台帐、事故隐患治理台账：","options":[{"key":"A","text":"业务范围或活动任务发生变化，颁布实施有关新的法律法规、标准规范或者原有适用法律法规、标准规范重新修订后三个月内"},{"key":"B","text":"组织机构和人员发生重大调整的"},{"key":"C","text":"技改技措项目、隐患项目投用前，区域位置、物料介质、工艺技术、设备、电气、仪表、公用工程或者操作参数等发生重大改变的"},{"key":"D","text":"国家、地方政府有明确要求或者外部环境发生重大变化的"}],"answer":"ABCD","explanation":"","subject":"风险分级防控和隐患排查治理管理规定"},{"id":"0290","type":"单选题","question":"遇有（ ）风以上（含五级风）、浓雾等恶劣天气，不应进行高处作业、露天攀登与悬空高处作业","options":[{"key":"A","text":"5"},{"key":"B","text":"6"},{"key":"C","text":"7"}],"answer":"A","explanation":"","subject":"高处作业管理规定"},{"id":"0291","type":"单选题","question":"坡度大于45°的斜坡上面实施的高处作业选择（ ）。","options":[{"key":"A","text":"Ⅰ级高处作业图标"},{"key":"B","text":"Ⅱ、Ⅲ级高处作业图标"},{"key":"C","text":"Ⅳ级高处作业图标"}],"answer":"A","explanation":"","subject":"高处作业管理规定"},{"id":"0292","type":"单选题","question":"在高空作业时，工具必须放在 ( ) 。","options":[{"key":"A","text":"工作服口袋里"},{"key":"B","text":"手提工具箱或工具袋里"},{"key":"C","text":"握住所有工具"},{"key":"D","text":"肩膀上"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0293","type":"单选题","question":"一个梯子上只允许( )人站立，严禁带人移动梯子。","options":[{"key":"A","text":"一"},{"key":"B","text":"二"},{"key":"C","text":"多人"}],"answer":"A","explanation":"","subject":"高处作业管理规定"},{"id":"0294","type":"单选题","question":"安全网应按GB5725-2009进行安装和坠落测试，结果应符合规范要求；（ ）至少检查一次，确认安全牢固后方可投入使用。","options":[{"key":"A","text":"每日"},{"key":"B","text":"每周"},{"key":"C","text":"每月"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0295","type":"单选题","question":"( )米及以上的高处作业与地面联系应设有相应的通讯装置，并由专人负责通讯联系。","options":[{"key":"A","text":"5"},{"key":"B","text":"15"},{"key":"C","text":"30"}],"answer":"C","explanation":"","subject":"高处作业管理规定"},{"id":"0296","type":"单选题","question":"移动式操作平台面积不应超过（）m2，高度不应超过（ ）m。","options":[{"key":"A","text":"5,10"},{"key":"B","text":"10,5"},{"key":"C","text":"10,10"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0297","type":"单选题","question":"( ) 防止高处作业人员发生坠落或发生坠落后将作业人员安全悬挂的个体防护装备。","options":[{"key":"A","text":"安全网"},{"key":"B","text":"安全绳"},{"key":"C","text":"安全带"}],"answer":"C","explanation":"","subject":"高处作业管理规定"},{"id":"0298","type":"单选题","question":"直梯应放置稳定，与地面夹角以（）为宜，梯子顶端应与建、构筑物靠牢。在容易滑偏的构件上靠梯时，梯子上端应用绳绑在上方牢固构件上。","options":[{"key":"A","text":"50°～60°"},{"key":"B","text":"60°～70°"},{"key":"C","text":"70°～80°"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0299","type":"单选题","question":"一般不得上下垂直进行高处作业，如需进行交叉作业，中间应设置安全防护层，坠落高度超过（ ）米的交叉作业，应设置双层防护。","options":[{"key":"A","text":"15"},{"key":"B","text":"24"},{"key":"C","text":"30"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0300","type":"单选题","question":"以下哪项不是作业审批人的职责( )","options":[{"key":"A","text":"核查作业许可证审批级别与公司制度中规定级别一致情况，核查各项审批环节符合相关制度要求的情况"},{"key":"B","text":"核查高处作业各项风险识别及管控措施落实情况"},{"key":"C","text":"编制高处作业施工方案。"}],"answer":"C","explanation":"","subject":"高处作业管理规定"},{"id":"0301","type":"单选题","question":"在接近或接触带电体条件下进行的带电高处作业，实施的高处作业选择（ ）。","options":[{"key":"A","text":"Ⅰ级高处作业图标"},{"key":"B","text":"Ⅱ、Ⅲ级高处作业图标"},{"key":"C","text":"Ⅳ级高处作业图标"}],"answer":"C","explanation":"","subject":"高处作业管理规定"},{"id":"0302","type":"单选题","question":"以下哪项不是临边作业( )。","options":[{"key":"A","text":"屋顶、地板"},{"key":"B","text":"栅格板的外缘"},{"key":"C","text":"2m有护栏的平台作业"}],"answer":"C","explanation":"","subject":"高处作业管理规定"},{"id":"0303","type":"单选题","question":"（ ）用于将安全带和锚固点或吊绳相连接，保护人体不坠落的系绳。","options":[{"key":"A","text":"安全绳"},{"key":"B","text":"锚固点"},{"key":"C","text":"吊绳"}],"answer":"A","explanation":"","subject":"高处作业管理规定"},{"id":"0304","type":"单选题","question":"存放梯子时，应将其（ ）并固定，避免倾倒砸伤人员。","options":[{"key":"A","text":"竖直"},{"key":"B","text":"横放"},{"key":"C","text":"任意"}],"answer":"B","explanation":"","subject":"高处作业管理规定"},{"id":"0305","type":"多选题","question":"Ⅱ、Ⅲ级高处作业图标有（ ）。","options":[{"key":"A","text":"在无平台、无护栏的塔、釜、炉、罐等化工容器、设备及架空管道上进行的高处作业"},{"key":"B","text":"在升降机（吊装）口、坑、井、池、沟、洞上面或附近进行的高处作业"},{"key":"C","text":"在易燃、易爆、易中毒、易灼伤的区域或转动设备附近进行的高处作业"}],"answer":"ABC","explanation":"","subject":"高处作业管理规定"},{"id":"0306","type":"多选题","question":"Ⅳ级高处作业图标有（ ）。","options":[{"key":"A","text":"降雪时进行的雪天高处作业"},{"key":"B","text":"在无立足点或无牢靠立足点的条件下进行的悬空高处作业"},{"key":"C","text":"作业高度在 h＞30 m的高处作业"}],"answer":"ABC","explanation":"","subject":"高处作业管理规定"}]});
